#
# Pytest CLI options, session-scoped fixtures, and suite filtering.
# Per-device outcomes live in ``board_cfg['_results']`` (see ``device_results``);
# tests loop over devices themselves and report one aggregated line each.

from __future__ import annotations

import os

import pytest

import deviations
from board_config import BOARDS, read_board_cfg
from device_results import SETUP_ERROR_KEY, report_details
from test_discovery import TestDiscovery
from test_gpio import TestGpio
from test_i2c import TestI2c
from test_led import TestLed
from test_spi import TestSpi
from test_uart import TestUart

_config = None

_SUITE_CLASS_MAP = {
    "spi": "Spi",
    "gpio": "Gpio",
    "irq": "Irq",
    "led": "Led",
    "i2c": "I2c",
    "uart": "Uart",
    "ipmi": "Ipmi",
}


def pytest_configure(config):
    global _config
    _config = config
    board = config.getoption("--board", default=None)
    deviations.configure(board, read_board_cfg(board) if board else None)


@pytest.hookimpl(trylast=True)
def pytest_runtest_logreport(report):
    """Print attached detail lines below the test result."""
    report_details(_config, report)


def pytest_addoption(parser):
    parser.addoption(
        "--board", required=True, help="Board name to load expected config for (e.g. HELLOWORLD547)"
    )
    parser.addoption(
        "--usb-path",
        action="store",
        default=None,
        metavar="PATH",
        help=(
            "Optional basename under /sys/bus/usb/devices (e.g. 1-1:1.0); "
            "else first matching device is used."
        ),
    )
    parser.addoption(
        "--suite",
        action="store",
        default=None,
        metavar="NAME",
        choices=list(_SUITE_CLASS_MAP),
        help="Run discovery + one test suite (spi, gpio, irq, led, i2c, uart, ipmi); omit for all.",
    )


def pytest_collection_modifyitems(config, items):
    """Drop UART tests when the board has no loopback config; filter by ``--suite``."""
    board_name = config.getoption("--board")
    cfg = read_board_cfg(board_name)
    if cfg is None:
        avail = ", ".join(sorted(BOARDS)) or "(none)"
        raise pytest.UsageError(f"Unknown board {board_name!r} (available: {avail})")
    if not TestUart.get_loopback_device_labels(cfg):
        kept, deselected = [], []
        for item in items:
            name = item.cls.__name__ if item.cls else ""
            if "Uart" in name:
                deselected.append(item)
            else:
                kept.append(item)
        if deselected:
            config.hook.pytest_deselected(items=deselected)
            items[:] = kept

    suite = config.getoption("--suite", default=None)
    if not suite:
        return
    cls_suffix = _SUITE_CLASS_MAP[suite]
    selected, deselected = [], []
    for item in items:
        name = item.cls.__name__ if item.cls else ""
        if "Discovery" in name:
            selected.append(item)
        elif suite == "irq":
            if any(tag in name for tag in ("Irq", "Gpio")):
                selected.append(item)
            else:
                deselected.append(item)
        elif cls_suffix in name:
            selected.append(item)
        else:
            deselected.append(item)
    if deselected:
        config.hook.pytest_deselected(items=deselected)
        items[:] = selected


@pytest.fixture(scope="session")
def board_name(request):
    return request.config.getoption("--board")


@pytest.fixture(scope="session")
def usb_path(request):
    return request.config.getoption("--usb-path")


@pytest.fixture(scope="session")
def board_cfg(board_name):
    cfg = read_board_cfg(board_name)
    if cfg is None:
        avail = ", ".join(sorted(BOARDS)) or "(none)"
        pytest.skip(f"unknown board {board_name!r} (available: {avail})")
    cfg.setdefault("_results", {})
    TestGpio.get_expected_configs(cfg)
    return cfg


# ------------------------- Discovery -------------------------


@pytest.fixture(scope="session")
def usb_sysfs(board_cfg, usb_path):
    if not TestDiscovery.is_driver_loaded():
        pytest.skip(
            f"lstp kernel module is not loaded (missing {TestDiscovery.LSTP_MODULE_SYSFS}); "
            "load with: sudo modprobe lstp"
        )
    try:
        resolved = TestDiscovery.choose_usb_basename(
            str(board_cfg.get("device_name") or ""), usb_path
        )
    except ValueError as e:
        pytest.fail(f"LSTP device not found: {e}")
    path = os.path.join(TestDiscovery.USB_DEVICES_ROOT, resolved)
    if not os.path.isdir(path):
        pytest.fail(f"LSTP device not found: {path} does not exist")
    return path


@pytest.fixture(scope="session")
def lstp_channels(usb_sysfs):
    return TestDiscovery.walk_channels(usb_sysfs)


@pytest.fixture(scope="session")
def spi_masters(lstp_channels):
    """SPI channel label -> sysfs master name (``spiN``)."""
    return {
        ch["name"]: ch["dev_name"]
        for ch in lstp_channels
        if ch["type"] == "spi" and ch.get("name") and ch.get("dev_name")
    }


@pytest.fixture(scope="session")
def gpio_chips(lstp_channels):
    return {
        ch["name"]: ch["dev_name"] for ch in lstp_channels if ch["type"] == "gpio" and ch["name"]
    }


@pytest.fixture(scope="session")
def led_devices(board_cfg):
    """Return LED sysfs names from ``gpio.devices`` rows tagged ``led``."""
    return list(TestLed.get_expected_configs(board_cfg)["led_devices"])


@pytest.fixture(scope="session")
def usb_leds(usb_sysfs):
    """Return LED names discovered under ``<usb>/leds/``."""
    return TestLed.discover_usb_leds(usb_sysfs)


@pytest.fixture
def led_reset(led_devices):
    """Clear patterns and park every configured LED around each test."""
    if not led_devices:
        pytest.skip(TestLed.NO_DEVICES)
    present = [name for name in led_devices if os.path.isdir(os.path.join(TestLed.LEDS_ROOT, name))]
    TestLed.clear_pattern_all(present)
    for name in present:
        TestLed.reset_led(name)
    yield
    TestLed.clear_pattern_all(present)
    for name in present:
        TestLed.reset_led(name)


@pytest.fixture(scope="session")
def i2c_buses(lstp_channels):
    return {
        ch["name"]: int(ch["dev_name"].removeprefix("i2c-"))
        for ch in lstp_channels
        if ch["type"] == "i2c" and ch["name"]
    }


@pytest.fixture(scope="session")
def uart_devices(lstp_channels):
    return {
        ch["name"]: ch["dev_name"] for ch in lstp_channels if ch["type"] == "uart" and ch["name"]
    }


@pytest.fixture(scope="session")
def ipmi_devices(lstp_channels):
    return {
        ch["name"]: ch["dev_name"] for ch in lstp_channels if ch["type"] == "ipmi" and ch["name"]
    }


# ------------------------- Device Setup / Teardown -------------------------


@pytest.fixture(scope="session")
def spidev_devices(spi_masters, board_cfg, lstp_channels, request):
    """Bind spidev, or return ``{_error: reason}`` when the bind could not run.

    Raising here would be reported as ERROR on every test requesting this
    session fixture, bypassing the per-device dependency map; ``pytest.skip``
    still propagates, since a skipped suite is the intended outcome.
    """
    try:
        ctx = TestSpi.spidev_install(spi_masters, board_cfg, lstp_channels)
    except pytest.fail.Exception as e:
        return {SETUP_ERROR_KEY: str(e) or "spidev install failed"}
    except Exception as e:  # noqa: BLE001 — surfaced per device by the SPI tests
        return {SETUP_ERROR_KEY: f"{e.__class__.__name__}: {e}"}
    request.addfinalizer(lambda: TestSpi.spidev_teardown(ctx))
    return ctx


@pytest.fixture(scope="session")
def i2c_eeproms(board_cfg, i2c_buses, request):
    """Instantiate at24 EEPROMs, or return ``{_error: reason}`` on setup failure."""
    i2c_cfg = board_cfg.get("i2c", {})
    try:
        contexts = TestI2c.i2c_eeprom_install(i2c_cfg, i2c_buses)
    except pytest.fail.Exception as e:
        return {SETUP_ERROR_KEY: str(e) or "EEPROM install failed"}
    except Exception as e:  # noqa: BLE001 — surfaced per device by the I2C tests
        return {SETUP_ERROR_KEY: f"{e.__class__.__name__}: {e}"}
    request.addfinalizer(lambda: TestI2c.i2c_eeprom_teardown(contexts))
    return contexts

# SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: Apache-2.0
#
# USB sysfs discovery, dmesg log, and channel structure validation.
#
# Board config: ``init`` section in boards/<board>.yaml
#   spi:   [channel_name, ...]
#   gpio:  [channel_name, ...]
#   i2c:   [channel_name, ...]
#   uart:  [channel_name, ...]
#   ipmi:  [channel_name, ...]
#   mmio:  [channel_name, ...]
#
# Note: discovery tests always run at the beginning of all suites.

from __future__ import annotations

import os
import re
import subprocess
import warnings

import pytest

import priv
from device_results import DeviceRunner


class TestDiscovery:
    """Resolve LSTP USB sysfs and discover child SPI, GPIO, I2C, UART, IPMI, and MMIO."""

    LSTP_MODULE_SYSFS = "/sys/module/lstp"
    USB_DEVICES_ROOT = "/sys/bus/usb/devices"
    SPI_MASTER_CLASS = "/sys/class/spi_master"
    GPIO_BUS_DEVICES = "/sys/bus/gpio/devices"
    I2C_DEVICES_ROOT = "/sys/bus/i2c/devices"
    TTY_CLASS = "/sys/class/tty"
    MISC_CLASS = "/sys/class/misc"
    DEV_ROOT = "/dev"
    _MISC_CHANNEL_TYPES = frozenset({"ipmi", "mmio"})
    LSTP_USB_VID = "0955"
    _DMESG_ERR_LEVELS = {0, 1, 2, 3}  # emerg/alert/crit/err -- hard fail
    _DMESG_WARN_LEVELS = {4}  # warn -- soft warning
    _DMESG_LOG_MAX_LINES = 10

    # dmesg -r line: ``<level>[ts] [<subsystem> <bus_id>: ]<msg>``. ``\S+?`` is
    # non-greedy because ``bus_id`` may contain ``:`` (e.g. ``1-1.2.1:1.2``).
    _DMESG_LINE_RE = re.compile(
        r"""^
        <(\d+)>                       # 1: syslog priority/level
        \[\s*(\d+\.\d+)\]             # 2: monotonic timestamp
        \s*
        (                             # 3: full message body
            (?:(\w+)\s+(\S+?):\s)?    # 4,5: optional <subsystem> <bus_id> prefix
            .*
        )
        $""",
        re.VERBOSE,
    )
    _CHANNEL_TYPE_RE = re.compile(
        r"^(?:(?P<spi>spi\d+)|(?P<i2c>i2c-\d+)|(?P<gpio>gpiochip\d+)"
        r"|(?P<uart>ttyLSTP\d+)|(?P<ipmi>ipmi-lstp\d+)"
        r"|(?P<mmio>lstp_mmio_\d+))$"
    )

    @classmethod
    def _format_dmesg_log_lines(cls, lines: list[str], max_lines: int | None = None) -> str:
        """Join *lines* for assert/warn text, truncating long logs."""
        limit = cls._DMESG_LOG_MAX_LINES if max_lines is None else max_lines
        if len(lines) <= limit:
            return "\n".join(lines)
        shown = lines[:limit]
        omitted = len(lines) - limit
        return "\n".join(shown) + f"\n... ({omitted} more line{'s' if omitted != 1 else ''})"

    @classmethod
    def _run(cls, cmd: list[str], **kwargs) -> subprocess.CompletedProcess[str]:
        return subprocess.run(cmd, capture_output=True, text=True, check=True, **kwargs)

    @classmethod
    def is_driver_loaded(cls) -> bool:
        """Return True when the lstp kernel module is loaded."""
        return os.path.isdir(cls.LSTP_MODULE_SYSFS)

    @classmethod
    def discover_usb_paths(cls, device_name: str) -> list[str]:
        """Return sysfs basenames where driver is ``lstp`` and ``name`` matches *device_name*."""
        needle = device_name.strip().casefold()
        if not needle:
            return []
        root = cls.USB_DEVICES_ROOT
        if not os.path.isdir(root):
            return []
        matches: list[str] = []
        for entry in sorted(os.listdir(root)):
            drv = os.path.join(root, entry, "driver")
            try:
                driver_target = os.readlink(drv) if os.path.islink(drv) else None
            except OSError:
                continue
            if os.path.basename(driver_target or "") != "lstp":
                continue
            intf_path = os.path.join(root, entry, "lstp", "name")
            if not os.path.isfile(intf_path):
                continue
            try:
                with open(intf_path, encoding="utf-8") as f:
                    reported = f.read().strip()
            except OSError:
                continue
            if reported.casefold() == needle:
                matches.append(entry)
        return matches

    @classmethod
    def choose_usb_basename(cls, device_name: str, usb_path_cli: str | None) -> str:
        """Return sysfs basename for *device_name*; prefer *usb_path_cli*.

        Raises ``ValueError`` when no match is found.
        """
        paths = cls.discover_usb_paths(device_name)
        if not paths:
            raise ValueError(f"No USB sysfs node with lstp driver and name={device_name!r}")
        if usb_path_cli is not None:
            if usb_path_cli not in paths:
                raise ValueError(f"--usb-path {usb_path_cli!r} not found among {paths!r}")
            return usb_path_cli
        return paths[0]

    # ------------------------- Channel walk -------------------------

    @classmethod
    def get_channel_type(cls, device_link: str) -> tuple[str, str] | None:
        """Classify a channel "device" symlink by its target basename.

        Return (type, dev_name) or None if unrecognised.
        """
        target = os.path.basename(os.path.realpath(device_link))
        m = cls._CHANNEL_TYPE_RE.match(target)
        if not m:
            return None
        for ch_type in ("spi", "i2c", "gpio", "uart", "ipmi", "mmio"):
            if m.group(ch_type):
                return ch_type, target
        return None

    @classmethod
    def walk_channels(cls, usb_sysfs: str) -> list[dict]:
        """Walk "lstp/channel/<N>/" and return structured info per channel."""
        channel_dir = os.path.join(usb_sysfs, "lstp", "channel")
        if not os.path.isdir(channel_dir):
            return []

        channels: list[dict] = []
        for entry in sorted(os.listdir(channel_dir)):
            if not entry.isdigit():
                continue
            ch_path = os.path.join(channel_dir, entry)
            info: dict = {
                "id": int(entry),
                "name": None,
                "type": None,
                "dev_name": None,
                "has_enable": os.path.isfile(os.path.join(ch_path, "enable")),
                "has_name": False,
                "has_device": False,
            }

            name_file = os.path.join(ch_path, "name")
            if os.path.isfile(name_file):
                with open(name_file, encoding="utf-8") as f:
                    info["name"] = f.read().strip()
                info["has_name"] = True

            dev_link = os.path.join(ch_path, "device")
            if os.path.islink(dev_link):
                info["has_device"] = True
                result = cls.get_channel_type(dev_link)
                if result:
                    info["type"], info["dev_name"] = result

            channels.append(info)
        return channels

    # ------------------------- Device verification -------------------------

    @classmethod
    def verify_spi_device(cls, dev_name: str) -> list[str]:
        """Check SPI master exists under /sys/class/spi_master/."""
        problems: list[str] = []
        bus = os.path.join(cls.SPI_MASTER_CLASS, dev_name)
        if not os.path.exists(bus):
            problems.append(f"{dev_name} not found at {bus}")
        return problems

    @classmethod
    def verify_i2c_device(cls, dev_name: str) -> list[str]:
        """Check I2C bus_name exists at sysfs path and /dev/."""
        problems: list[str] = []
        bus = os.path.join(cls.I2C_DEVICES_ROOT, dev_name)
        if not os.path.exists(bus):
            problems.append(f"{dev_name} not found at {bus}")
        dev = os.path.join(cls.DEV_ROOT, dev_name)
        if not os.path.exists(dev):
            problems.append(f"{dev_name} not found at {dev}")
        return problems

    @classmethod
    def verify_gpio_device(cls, dev_name: str) -> list[str]:
        """Check GPIO chip exists at bus path and /dev/."""
        problems: list[str] = []
        bus = os.path.join(cls.GPIO_BUS_DEVICES, dev_name)
        if not os.path.exists(bus):
            problems.append(f"{dev_name} not found at {bus}")
        dev = os.path.join(cls.DEV_ROOT, dev_name)
        if not os.path.exists(dev):
            problems.append(f"{dev_name} not found at {dev}")
        return problems

    @classmethod
    def verify_uart_device(cls, dev_name: str) -> list[str]:
        """Check UART tty device exists at class path and /dev/."""
        problems: list[str] = []
        bus = os.path.join(cls.TTY_CLASS, dev_name)
        if not os.path.exists(bus):
            problems.append(f"{dev_name} not found at {bus}")
        dev = os.path.join(cls.DEV_ROOT, dev_name)
        if not os.path.exists(dev):
            problems.append(f"{dev_name} not found at {dev}")
        return problems

    @classmethod
    def verify_misc_device(cls, dev_name: str) -> list[str]:
        """Check IPMI or MMIO miscdevice exists at class path and /dev/."""
        problems: list[str] = []
        bus = os.path.join(cls.MISC_CLASS, dev_name)
        if not os.path.exists(bus):
            problems.append(f"{dev_name} not found at {bus}")
        dev = os.path.join(cls.DEV_ROOT, dev_name)
        if not os.path.exists(dev):
            problems.append(f"{dev_name} not found at {dev}")
        return problems

    _VERIFY_DISPATCH = {
        "spi": verify_spi_device.__func__,
        "i2c": verify_i2c_device.__func__,
        "gpio": verify_gpio_device.__func__,
        "uart": verify_uart_device.__func__,
    }

    # ------------------------- Misc helpers -------------------------

    @classmethod
    def dmesg_since_connection(
        cls, usb_port: str, own_bus_ids: set[str]
    ) -> tuple[list[str], list[str], list[str], list[str]]:
        """Return LSTP and general dmesg errors/warnings since last connect.

        Returns ``(lstp_errors, lstp_warnings, general_errors, general_warnings)``.
        A line is this board's LSTP when its prefix is ``lstp <usb_port>:`` or
        ``<subsystem> <bus_id>:`` with ``bus_id`` in *own_bus_ids*.
        All other lines go to the general buckets.
        """
        try:
            raw = priv.sudo_run(["dmesg", "-r"]).stdout
        except (subprocess.CalledProcessError, PermissionError, TimeoutError):
            return [], [], [], []

        # (level, ts, msg, subsystem or None, bus_id or None)
        parsed: list[tuple[int, float, str, str | None, str | None]] = []
        for line in raw.splitlines():
            m = cls._DMESG_LINE_RE.match(line)
            if m:
                parsed.append(
                    (int(m.group(1)), float(m.group(2)), m.group(3), m.group(4), m.group(5))
                )

        def is_lstp(subsystem: str | None, bus_id: str | None) -> bool:
            """``lstp <our_usb_port>:`` or any ``<subsystem> <bus_id>:`` we own."""
            if subsystem == "lstp":
                return bus_id == usb_port
            return bus_id is not None and bus_id in own_bus_ids

        def is_target_device(msg: str, subsystem: str | None, bus_id: str | None) -> bool:
            """``New USB device found`` for our port with the LSTP VID."""
            dev_port = usb_port.split(":")[0] if ":" in usb_port else usb_port
            return (
                "New USB device found" in msg
                and f"idVendor={cls.LSTP_USB_VID}" in msg
                and subsystem == "usb"
                and bus_id == dev_port
            )

        # Most recent session start (newest first).
        connect_ts = None
        for _, ts, msg, subsystem, bus_id in reversed(parsed):
            if (
                is_target_device(msg, subsystem, bus_id)
                or "deregistering interface driver lstp" in msg
            ):
                connect_ts = ts
                break

        # Fallback for a rotated buffer: anchor to earliest line we own.
        if connect_ts is None:
            for _, ts, _, subsystem, bus_id in parsed:
                if is_lstp(subsystem, bus_id):
                    connect_ts = ts
                    break

        if connect_ts is None:
            return [], [], [], []

        lstp_errors: list[str] = []
        lstp_warnings: list[str] = []
        general_errors: list[str] = []
        general_warnings: list[str] = []
        for level, ts, msg, subsystem, bus_id in parsed:
            if ts < connect_ts:
                continue
            if level in cls._DMESG_ERR_LEVELS:
                (lstp_errors if is_lstp(subsystem, bus_id) else general_errors).append(msg)
            elif level in cls._DMESG_WARN_LEVELS:
                (lstp_warnings if is_lstp(subsystem, bus_id) else general_warnings).append(msg)
        return lstp_errors, lstp_warnings, general_errors, general_warnings

    # ------------------------- Discovery Tests -------------------------

    def test_connection(self, board_cfg, usb_path) -> None:
        """Verify lstp is loaded and USB device is bound."""
        assert self.is_driver_loaded(), (
            f"lstp kernel module is not loaded (missing {self.LSTP_MODULE_SYSFS}); "
            "load with: sudo modprobe lstp"
        )

        device_name = str(board_cfg.get("device_name") or "")
        paths = self.discover_usb_paths(device_name)
        assert paths, (
            "No LSTP device found: no USB sysfs node with lstp driver "
            f"and name matching {device_name!r}"
        )
        if usb_path is not None:
            assert usb_path in paths, (
                f"--usb-path {usb_path!r} not among discovered devices: {paths!r}"
            )

    def test_dmesg_log(self, usb_sysfs: str, board_cfg: dict, lstp_channels) -> None:
        """LSTP errors fail; LSTP warnings + any general err/warn only warn."""
        port = os.path.basename(usb_sysfs.rstrip("/"))
        # Kernel-assigned bus_ids (e.g. ``i2c-22``)
        own_bus_ids = {ch["dev_name"] for ch in lstp_channels if ch.get("dev_name")}
        lstp_errors, lstp_warnings, general_errors, general_warnings = type(
            self
        ).dmesg_since_connection(port, own_bus_ids)

        if lstp_warnings:
            warnings.warn(
                f"LSTP dmesg warnings for {port} since device connection:\n"
                + self._format_dmesg_log_lines(lstp_warnings),
                UserWarning,
                stacklevel=2,
            )
        if general_errors:
            warnings.warn(
                "General dmesg errors since device connection:\n"
                + self._format_dmesg_log_lines(general_errors),
                UserWarning,
                stacklevel=2,
            )
        if general_warnings:
            warnings.warn(
                "General dmesg warnings since device connection:\n"
                + self._format_dmesg_log_lines(general_warnings),
                UserWarning,
                stacklevel=2,
            )

        assert not lstp_errors, (
            f"LSTP dmesg errors for {port} since device connection:\n"
            + self._format_dmesg_log_lines(lstp_errors)
        )

    def _channel_structure_issues(
        self, ch: dict, expected_type: str | None = None
    ) -> tuple[list[str], list[str]]:
        """Return ``(missing, unexpected)`` structure issues for one walked channel."""
        missing: list[str] = []
        unexpected: list[str] = []
        if not ch["has_enable"]:
            missing.append("enable")
        if not ch["has_name"]:
            missing.append("name")
        if not ch["has_device"]:
            missing.append("device")
            return missing, unexpected

        ch_type, dev_name = ch["type"], ch["dev_name"]
        if ch_type is None:
            unexpected.append("unrecognised device target")
            return missing, unexpected

        if expected_type is not None and ch_type != expected_type:
            unexpected.append(f"type '{ch_type}' (expected '{expected_type}')")

        if ch_type in self._MISC_CHANNEL_TYPES:
            verify = type(self).verify_misc_device.__func__
        else:
            verify = self._VERIFY_DISPATCH.get(ch_type)
        if verify is None:
            unexpected.append(f"no verifier for type '{ch_type}'")
        else:
            missing.extend(verify(self, dev_name))
        return missing, unexpected

    @staticmethod
    def _format_channel_issues(missing: list[str], unexpected: list[str]) -> str:
        """Build the per-device ``missing:`` / ``unexpected:`` detail block."""
        lines: list[str] = []
        if missing:
            lines.append(f"missing: {missing!r}")
        if unexpected:
            lines.append(f"unexpected: {unexpected!r}")
        return "\n".join(lines)

    def test_sysfs_structure(self, board_cfg: dict, usb_sysfs, lstp_channels) -> None:
        """Walk lstp/channel/ and verify device links, types, names, and enable."""
        assert lstp_channels, f"lstp/channel not found or empty under {usb_sysfs}"

        init = board_cfg["init"]
        expected: dict[str, str] = {}
        for ch_type in ("spi", "gpio", "i2c", "uart", "ipmi", "mmio"):
            for name in init.get(ch_type, []):
                expected[name] = ch_type

        named = [ch["name"] for ch in lstp_channels if ch["name"]]
        dupes = sorted({n for n in named if named.count(n) > 1})
        assert not dupes, f"duplicate lstp channel name(s) in sysfs: {dupes}"

        by_name = {ch["name"]: ch for ch in lstp_channels if ch["name"]}
        runner = DeviceRunner(board_cfg, "discovery", "sysfs_structure")

        for name, exp_type in expected.items():

            def _one(n=name, t=exp_type) -> None:
                ch = by_name.get(n)
                if ch is None:
                    pytest.fail(f"missing: {t} channel")
                missing, unexpected = self._channel_structure_issues(ch, expected_type=t)
                detail = self._format_channel_issues(missing, unexpected)
                assert not detail, detail

            runner.run(name, _one)

        for name, ch in by_name.items():
            if name in expected:
                continue

            def _one(c=ch) -> None:
                ch_type = c.get("type") or "unknown"
                missing, unexpected = self._channel_structure_issues(c)
                unexpected = [f"{ch_type} channel", *unexpected]
                pytest.fail(self._format_channel_issues(missing, unexpected))

            runner.run(name, _one)

        for ch in lstp_channels:
            if ch["name"]:
                continue
            missing, unexpected = self._channel_structure_issues(ch)
            detail = self._format_channel_issues(missing, unexpected)
            if not detail:
                continue

            def _one(msg=detail) -> None:
                pytest.fail(msg)

            runner.run(f"ch{ch['id']}", _one)

        runner.finish()

