# SPI master count, chip-select count, and device node validation.
#
# Board config: ``spi`` section in boards/<board>.yaml
#   devices:   channel_name -> [cs_count, clock_speed_hz, spi_mode]
#   spi_flash: channel_name -> {cs: [flash_type, [jedec_id], size, start_addr]}
#   bandwidth: expected_bandwidth (ops/s)
