from __future__ import annotations

import logging
import os
import random
import stat
import struct
import subprocess
import time

import pytest

import priv
from device_results import DeviceRunner, SETUP_ERROR_KEY

try:
    import spidev
except ImportError:
    spidev = None

logger = logging.getLogger(__name__)


class TestSpi:
    """SPI masters and device nodes vs board YAML."""

    NO_DEVICES = "no spi.devices in board YAML"
    NO_SECTION = "no spi in board YAML"
    NO_SPI_FLASH = "no spi.spi_flash in board YAML"
    NO_BANDWIDTH = "no spi.bandwidth in board YAML"
    NO_BANDWIDTH_CASES = "no spi.bandwidth.cases in board YAML"

    SPI_BUS_DEVICES = "/sys/bus/spi/devices"
    SPIDEV_BIND = "/sys/bus/spi/drivers/spidev/bind"
    SPIDEV_UNBIND = "/sys/bus/spi/drivers/spidev/unbind"
    LSTP_MODULE_SYSFS = "/sys/module/lstp"
    LSTP_AUTO_BIND_PARAM = "/sys/module/lstp/parameters/auto_bind_spidev"

    # JEDEC standard defaults (universal for all SPI NOR flash)
    JEDEC_DEFAULTS = {
        "page_size": 256,
        "sector_size": 4096,
        "addr_bytes": 3,
        "cmd_write_enable": 0x06,
        "cmd_read_status": 0x05,
        "cmd_read_jedec_id": 0x9F,
        "cmd_read": 0x03,
        "cmd_page_program": 0x02,
        "cmd_sector_erase": 0x20,
        "cmd_release_power_down": 0xAB,
        "status_busy_mask": 0x01,
        "erase_timeout": 2.0,
        "program_timeout": 1.0,
    }

    # Bus configuration fallbacks (override via board YAML spi.spi_speed_hz / spi_mode)
    DEFAULT_SPI_SPEED_HZ = 1_000_000
    DEFAULT_SPI_MODE = 0
    BANDWIDTH_MIN_RUNTIME_S = 5.0
    BANDWIDTH_MIN_CYCLES = 1000

    @classmethod
    def _run(cls, cmd: list[str], **kwargs) -> subprocess.CompletedProcess[str]:
        return subprocess.run(cmd, capture_output=True, text=True, check=True, **kwargs)

    @classmethod
    def get_expected_configs(cls, cfg: dict) -> dict:
        """Return ``spi.devices`` as ``{channel_name: config}``."""
        return cfg.get("spi", {}).get("devices", {})

    @staticmethod
    def _flash_parent_key(flash_id: str) -> str:
        """Map ``label@CSn`` flash id to its parent SPI channel label."""
        return flash_id.rsplit("@CS", 1)[0]

    @staticmethod
    def _bandwidth_case_key(flash_id: str, test_bytes: int) -> str:
        return f"{flash_id} len={test_bytes}"

    @staticmethod
    def _bandwidth_parent_key(case_key: str) -> str:
        return case_key.rsplit(" len=", 1)[0]

    @classmethod
    def _list_cs_devices(cls, masters) -> list[str]:
        """Return SPI child device names (e.g. ``spi0.0``) for *masters*.

        *masters* is an iterable of sysfs master names (``spiN``).
        """
        if not os.path.isdir(cls.SPI_BUS_DEVICES):
            return []
        result: list[str] = []
        for master in masters:
            prefix = f"{master}."
            result.extend(
                e for e in sorted(os.listdir(cls.SPI_BUS_DEVICES)) if e.startswith(prefix)
            )
        return result

    @classmethod
    def _wait_for_spi_children(cls, master: str, timeout_s: float = 5.0) -> list[str]:
        deadline = time.monotonic() + timeout_s
        while time.monotonic() < deadline:
            cs = cls._list_cs_devices([master])
            if cs:
                return cs
            time.sleep(0.5)
        return []

    @classmethod
    def _read_auto_bind_spidev(cls) -> str:
        """Read ``auto_bind_spidev`` from the loaded lstp module."""
        if not os.path.isdir(cls.LSTP_MODULE_SYSFS):
            return "unknown"
        try:
            with open(cls.LSTP_AUTO_BIND_PARAM, encoding="ascii") as f:
                raw = f.read().strip().lower()
        except OSError:
            return "unknown"
        if raw in ("y", "1", "yes", "true"):
            return "on"
        if raw in ("n", "0", "no", "false"):
            return "off"
        return "unknown"

    @classmethod
    def _require_spi_children(cls, master: str) -> list[str]:
        """Return sysfs SPI child names for one master; fail if none appear."""
        cs = cls._list_cs_devices([master])
        if cs:
            return cs

        auto_bind = cls._read_auto_bind_spidev()
        if auto_bind != "off":
            cs = cls._wait_for_spi_children(master)
        if cs:
            return cs

        base = f"No SPI children under {cls.SPI_BUS_DEVICES} for {master}"
        if auto_bind == "on":
            msg = (
                f"{base}; auto_bind_spidev=1 but no spiX.Y devices appeared "
                "(check firmware/CS configuration)"
            )
        elif auto_bind == "off":
            msg = f"{base} (auto_bind_spidev=0)"
        else:
            msg = base
        logger.warning(msg)
        pytest.fail(msg)

    @staticmethod
    def _masters_only(ctx: dict) -> dict[str, dict[int, str]]:
        """Filter out internal keys, returning only master -> {cs: devpath}."""
        return {k: v for k, v in ctx.items() if not k.startswith("_")}

    @classmethod
    def _discovered_keys(cls, ctx: dict) -> set[str]:
        """Return discovered channel labels for master keys in ``spidev_devices``."""
        master_labels = ctx.get("_master_labels", {})
        return {master_labels.get(master, master) for master in cls._masters_only(ctx)}

    @classmethod
    def _devs_for_label(cls, ctx: dict, label: str) -> dict[int, str]:
        """Return ``{cs: /dev/spidevX.Y}`` for channel *label*, or ``{}`` if missing."""
        master_labels = ctx.get("_master_labels", {})
        masters = cls._masters_only(ctx)
        for master, lab in master_labels.items():
            if lab == label:
                return masters.get(master, {})
        return masters.get(label, {})

    @classmethod
    def spidev_install(
        cls, spi_masters: dict, board_cfg: dict, lstp_channels: list[dict] | None = None
    ) -> dict:
        """Bind the spidev driver to every CS device on each discovered master.

        *spi_masters* maps channel label -> sysfs master name (``spiN``).
        """
        if "spi" not in board_cfg:
            pytest.skip(cls.NO_SECTION)
        if not board_cfg.get("spi", {}).get("devices"):
            pytest.skip(cls.NO_DEVICES)

        priv.sudo_run(["modprobe", "spidev"])

        if not spi_masters:
            pytest.fail(
                "No SPI masters discovered from LSTP channels; check discovery before SPI tests"
            )

        all_cs: list[str] = []
        for master in spi_masters.values():
            all_cs.extend(cls._require_spi_children(master))

        we_bound: list[str] = []
        for dev_name in all_cs:
            drv_link = os.path.join(cls.SPI_BUS_DEVICES, dev_name, "driver")
            if os.path.islink(drv_link) and os.path.basename(os.readlink(drv_link)) == "spidev":
                continue
            override = os.path.join(cls.SPI_BUS_DEVICES, dev_name, "driver_override")
            try:
                priv.sysfs_write(override, "spidev\n")
                priv.sysfs_write(cls.SPIDEV_BIND, f"{dev_name}\n")
                we_bound.append(dev_name)
            except PermissionError as e:
                pytest.fail(f"Cannot bind spidev to {dev_name}: {e}")
            except OSError:
                pass

        time.sleep(0.5)

        devices: dict[str, dict[int, str]] = {}
        master_labels = {
            ch["dev_name"]: ch["name"]
            for ch in lstp_channels or []
            if ch.get("type") == "spi" and ch.get("dev_name") and ch.get("name")
        }
        for dev_name in all_cs:
            master = dev_name.rsplit(".", 1)[0]
            bus = master.removeprefix("spi")
            cs = int(dev_name.rsplit(".", 1)[1])
            path = f"/dev/spidev{bus}.{cs}"
            if os.path.exists(path):
                devices.setdefault(master, {})[cs] = path

        devices["_we_bound"] = we_bound
        devices["_master_labels"] = master_labels
        return devices

    @classmethod
    def spidev_teardown(cls, ctx: dict) -> None:
        """Undo :meth:`spidev_install` bindings; leave pre-existing spidev bindings untouched."""
        for dev_name in ctx.get("_we_bound", []):
            try:
                priv.sysfs_write(cls.SPIDEV_UNBIND, f"{dev_name}\n")
            except OSError:
                pass
            override = os.path.join(cls.SPI_BUS_DEVICES, dev_name, "driver_override")
            try:
                priv.sysfs_write(override, "\n")
            except OSError:
                pass

    # ------------------------- SPI Flash Helpers -------------------------

    @classmethod
    def get_spi_flash_ids(cls, cfg: dict) -> list[str]:
        """Return SPI flash IDs as ``label@CSn`` strings."""
        flash_cfg = cfg.get("spi", {}).get("spi_flash") or {}
        return [f"{label}@CS{cs}" for label, devs in flash_cfg.items() for cs in devs]

    @classmethod
    def resolve_spi_flash(
        cls, flash_id: str, board_cfg: dict, lstp_channels: list[dict], spidev_devices: dict
    ) -> dict:
        """Resolve a single SPI flash device from its ``label@CSn`` ID."""
        label, cs_str = flash_id.rsplit("@CS", 1)
        cs = int(cs_str)

        flash_cfg = board_cfg.get("spi", {}).get("spi_flash", {})
        if label not in flash_cfg or cs not in flash_cfg[label]:
            raise ValueError(f"SPI flash not configured: {flash_id!r}")

        flash_type, jedec_id, size, start_addr = flash_cfg[label][cs]

        dev_name = None
        for ch in lstp_channels:
            if ch["type"] == "spi" and ch["name"] == label:
                dev_name = ch["dev_name"]
                break
        if dev_name is None:
            raise ValueError(f"SPI device not found: {label!r}")

        masters = cls._masters_only(spidev_devices)
        paths = masters.get(dev_name, {})
        spidev_path = paths.get(cs)
        if spidev_path is None:
            raise ValueError(f"CS{cs} not available for {label}")

        dev_cfg = board_cfg.get("spi", {}).get("devices", {}).get(label, [])
        result = {
            "flash_id": flash_id,
            "spidev_path": spidev_path,
            "flash_type": flash_type,
            "size": size,
            "start_addr": start_addr,
            "jedec_id": tuple(jedec_id),
            **cls.JEDEC_DEFAULTS,
        }
        if isinstance(dev_cfg, list) and len(dev_cfg) >= 2:
            result["spi_speed_hz"] = dev_cfg[1]
        if isinstance(dev_cfg, list) and len(dev_cfg) >= 3:
            result["spi_mode"] = dev_cfg[2]
        return result

    @classmethod
    def _open_flash(cls, path: str, params: dict | None = None):
        """Open a spidev device and configure bus parameters."""
        cfg = params or cls.JEDEC_DEFAULTS
        base = os.path.basename(path).removeprefix("spidev")
        bus_str, cs_str = base.split(".")
        dev = spidev.SpiDev()
        dev.open(int(bus_str), int(cs_str))
        dev.max_speed_hz = cfg.get("spi_speed_hz", cls.DEFAULT_SPI_SPEED_HZ)
        dev.mode = cfg.get("spi_mode", cls.DEFAULT_SPI_MODE)
        dev.bits_per_word = 8
        if cfg.get("cmd_release_power_down"):
            dev.xfer2([cfg["cmd_release_power_down"], 0x00, 0x00, 0x00])
            time.sleep(0.005)
        return dev

    @staticmethod
    def _encode_addr(addr: int, n: int) -> list[int]:
        """Encode *addr* as *n* big-endian bytes."""
        return [(addr >> (8 * i)) & 0xFF for i in range(n - 1, -1, -1)]

    @classmethod
    def _flash_wait_ready(cls, dev, params: dict, timeout: float = 5.0) -> None:
        """Poll Status Register-1 BUSY bit until clear or *timeout*."""
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if not (dev.xfer2([params["cmd_read_status"], 0])[1] & params["status_busy_mask"]):
                return
        raise TimeoutError("SPI flash BUSY did not clear within timeout")

    @classmethod
    def _flash_sector_erase(cls, dev, addr: int, params: dict) -> None:
        """Write-Enable + Sector Erase + wait ready."""
        dev.xfer2([params["cmd_write_enable"]])
        dev.xfer2([params["cmd_sector_erase"], *cls._encode_addr(addr, params["addr_bytes"])])
        cls._flash_wait_ready(dev, params, timeout=params["erase_timeout"])

    @classmethod
    def _flash_page_program(cls, dev, addr: int, data: bytes, params: dict) -> None:
        """Write-Enable + Page Program up to *page_size* bytes + wait ready."""
        dev.xfer2([params["cmd_write_enable"]])
        cmd = [params["cmd_page_program"], *cls._encode_addr(addr, params["addr_bytes"])]
        dev.xfer2(cmd + list(data))
        cls._flash_wait_ready(dev, params, timeout=params["program_timeout"])

    @classmethod
    def _flash_read_data(cls, dev, addr: int, length: int, params: dict) -> bytes:
        """Read *length* bytes using page-sized SPI transfers."""
        chunk = params["page_size"]
        addr_n = params["addr_bytes"]
        buf = bytearray()
        for off in range(0, length, chunk):
            n = min(chunk, length - off)
            cmd = [params["cmd_read"]] + cls._encode_addr(addr + off, addr_n)
            resp = dev.xfer2(cmd + [0] * n)
            buf.extend(resp[1 + addr_n : 1 + addr_n + n])
        return bytes(buf)

    # ------------------------- SPI Tests -------------------------

    @staticmethod
    def _require_spidev_setup(spidev_devices: dict) -> None:
        """Fail with the reason the ``spidev_devices`` fixture could not set up."""
        if err := spidev_devices.get(SETUP_ERROR_KEY):
            pytest.fail(f"spidev setup failed: {err}")

    def test_spi_children(self, board_cfg, spi_masters, request) -> None:
        """Each SPI master must have ``spiX.Y`` children under sysfs."""
        expected = self.get_expected_configs(board_cfg)
        if not expected:
            pytest.skip(self.NO_DEVICES)

        runner = DeviceRunner(
            board_cfg, "spi", "spi_children", skip=self.NO_DEVICES, request=request
        )
        for label in expected:

            def _one(lab=label) -> None:
                master = spi_masters.get(lab)
                if master is None:
                    pytest.fail("SPI master not discovered from LSTP channels")
                self._require_spi_children(master)

            runner.run(label, _one)
        runner.finish()

    def test_spidev_devices_exist(self, board_cfg, spidev_devices, request) -> None:
        """Each SPI master must have /dev/spidev entries after driver binding."""
        expected = self.get_expected_configs(board_cfg)
        if not expected:
            pytest.skip(self.NO_DEVICES)

        runner = DeviceRunner(
            board_cfg,
            "spi",
            "spidev_devices_exist",
            requires=[("spi", "spi_children")],
            skip=self.NO_DEVICES,
            request=request,
        )
        for label in expected:

            def _one(lab=label) -> None:
                self._require_spidev_setup(spidev_devices)
                if lab not in self._discovered_keys(spidev_devices):
                    pytest.fail(
                        "SPI device not found "
                        f"(discovered: {sorted(self._discovered_keys(spidev_devices))!r})"
                    )
                assert self._devs_for_label(spidev_devices, lab), (
                    "no /dev/spidev entries after driver binding"
                )

            runner.run(label, _one)
        runner.finish()

    def test_spidev_cs_count(self, board_cfg, spidev_devices, request) -> None:
        """Chip-select count per master must match the board YAML expectation."""
        expected = self.get_expected_configs(board_cfg)
        if not expected:
            pytest.skip(self.NO_DEVICES)

        runner = DeviceRunner(
            board_cfg,
            "spi",
            "spidev_cs_count",
            requires=[("spi", "spi_children")],
            skip=self.NO_DEVICES,
            request=request,
        )
        for label, cfg in expected.items():

            def _one(lab=label, conf=cfg) -> None:
                self._require_spidev_setup(spidev_devices)
                expected_cs = conf[0] if isinstance(conf, list) else conf
                actual_cs = len(self._devs_for_label(spidev_devices, lab))
                assert actual_cs == expected_cs, (
                    f"CS count mismatch: expected {expected_cs}, got {actual_cs}"
                )

            runner.run(label, _one)
        runner.finish()

    def test_spidev_nodes_accessible(self, board_cfg, spidev_devices, request) -> None:
        """Every discovered /dev/spidevX.Y node must be a character device."""
        expected = self.get_expected_configs(board_cfg)
        if not expected:
            pytest.skip(self.NO_DEVICES)

        runner = DeviceRunner(
            board_cfg,
            "spi",
            "spidev_nodes_accessible",
            requires=[("spi", "spi_children")],
            skip=self.NO_DEVICES,
            request=request,
        )
        for label in expected:

            def _one(lab=label) -> None:
                self._require_spidev_setup(spidev_devices)
                for path in self._devs_for_label(spidev_devices, lab).values():
                    assert os.path.exists(path), f"SPI device {path} does not exist"
                    assert stat.S_ISCHR(os.stat(path).st_mode), (
                        f"SPI device {path} is not a character device"
                    )

            runner.run(label, _one)
        runner.finish()

    # ------------------------- SPI Flash Tests -------------------------

    def test_flash_jedec_id(self, board_cfg, lstp_channels, spidev_devices, request) -> None:
        """SPI flash JEDEC ID must match the expected value for the device type."""
        if spidev is None:
            pytest.skip("spidev python package not installed")
        flash_ids = self.get_spi_flash_ids(board_cfg)
        if not flash_ids:
            pytest.skip(self.NO_SPI_FLASH)

        runner = DeviceRunner(
            board_cfg,
            "spi",
            "flash_jedec_id",
            requires=[("spi", "spi_children", self._flash_parent_key)],
            request=request,
        )
        for flash_id in flash_ids:

            def _one(fid=flash_id) -> None:
                self._require_spidev_setup(spidev_devices)
                spi_flash = self.resolve_spi_flash(fid, board_cfg, lstp_channels, spidev_devices)
                dev = self._open_flash(spi_flash["spidev_path"], spi_flash)
                try:
                    resp = dev.xfer2([spi_flash["cmd_read_jedec_id"], 0, 0, 0])
                    jedec = tuple(resp[1:4])
                finally:
                    dev.close()
                expected = spi_flash["jedec_id"]
                assert jedec == expected, (
                    f"JEDEC ID mismatch on {spi_flash['spidev_path']}: "
                    f"got ({', '.join(f'0x{b:02x}' for b in jedec)}), "
                    f"expected ({', '.join(f'0x{b:02x}' for b in expected)}); "
                    f"full response: [{', '.join(f'0x{b:02x}' for b in resp)}]; "
                    f"speed={dev.max_speed_hz} mode={dev.mode}"
                )

            runner.run(flash_id, _one)
        runner.finish()

    def test_spi_bandwidth(self, board_cfg, lstp_channels, spidev_devices, request) -> None:
        """Each configured SPI flash must meet effective program and read bandwidth."""
        if spidev is None:
            pytest.skip("spidev python package not installed")

        flash_ids = self.get_spi_flash_ids(board_cfg)
        if not flash_ids:
            pytest.skip(self.NO_SPI_FLASH)

        bandwidth_cfg = board_cfg.get("spi", {}).get("bandwidth") or {}
        if not bandwidth_cfg:
            pytest.skip(self.NO_BANDWIDTH)

        bandwidth_cases = bandwidth_cfg.get("cases") or []
        if not bandwidth_cases:
            pytest.skip(self.NO_BANDWIDTH_CASES)
        for case in bandwidth_cases:
            assert isinstance(case, list) and len(case) == 2, (
                "each spi.bandwidth case must be [bytes, min_bps]"
            )
            assert int(case[0]) > 0, "spi.bandwidth case bytes must be greater than zero"
            assert float(case[1]) >= 0, "spi.bandwidth case min_bps must not be negative"

        runner = DeviceRunner(
            board_cfg,
            "spi",
            "spi_bandwidth",
            requires=[("spi", "flash_jedec_id", self._bandwidth_parent_key)],
            request=request,
        )
        for flash_id in flash_ids:
            for case in bandwidth_cases:
                test_bytes = int(case[0])
                min_bps = float(case[1])
                case_key = self._bandwidth_case_key(flash_id, test_bytes)

                def _one(fid=flash_id, length=test_bytes, floor=min_bps, key=case_key) -> None:
                    self._require_spidev_setup(spidev_devices)
                    spi_flash = self.resolve_spi_flash(
                        fid, board_cfg, lstp_channels, spidev_devices
                    )
                    page_size = spi_flash["page_size"]
                    sector_size = spi_flash["sector_size"]
                    start_addr = spi_flash["start_addr"]
                    erase_bytes = ((length + sector_size - 1) // sector_size) * sector_size
                    assert start_addr % sector_size == 0, (
                        f"SPI flash start_addr 0x{start_addr:x} must be sector-aligned"
                    )
                    assert start_addr + erase_bytes <= spi_flash["size"], (
                        f"SPI flash bandwidth window 0x{start_addr:x}-"
                        f"0x{start_addr + erase_bytes:x} exceeds configured size "
                        f"0x{spi_flash['size']:x}"
                    )

                    pretest_fill_byte = 0xA5
                    pattern = random.randbytes(length)
                    while pattern[0] == pretest_fill_byte:
                        pattern = random.randbytes(length)

                    dev = self._open_flash(spi_flash["spidev_path"], spi_flash)
                    try:
                        for offset in range(0, erase_bytes, sector_size):
                            self._flash_sector_erase(dev, start_addr + offset, spi_flash)

                        pretest_fill = bytes([pretest_fill_byte]) * length
                        for offset in range(0, length, page_size):
                            self._flash_page_program(
                                dev,
                                start_addr + offset,
                                pretest_fill[offset : offset + page_size],
                                spi_flash,
                            )
                        written_fill = self._flash_read_data(dev, start_addr, length, spi_flash)
                        assert written_fill == pretest_fill, "SPI flash pretest fill did not verify"

                        for offset in range(0, erase_bytes, sector_size):
                            self._flash_sector_erase(dev, start_addr + offset, spi_flash)
                        erased = self._flash_read_data(dev, start_addr, erase_bytes, spi_flash)
                        not_erased_offset = next(
                            (offset for offset, value in enumerate(erased) if value != 0xFF), None
                        )
                        assert not_erased_offset is None, (
                            f"SPI flash erase left 0x{erased[not_erased_offset]:02x} "
                            f"at offset 0x{not_erased_offset:x}"
                        )

                        program_start = time.perf_counter()
                        for offset in range(0, length, page_size):
                            self._flash_page_program(
                                dev,
                                start_addr + offset,
                                pattern[offset : offset + page_size],
                                spi_flash,
                            )
                        program_elapsed = time.perf_counter() - program_start

                        read_cycles = 0
                        read_start = time.perf_counter()
                        while (
                            read_cycles < self.BANDWIDTH_MIN_CYCLES
                            or time.perf_counter() - read_start < self.BANDWIDTH_MIN_RUNTIME_S
                        ):
                            readback = self._flash_read_data(dev, start_addr, length, spi_flash)
                            read_cycles += 1
                            if readback != pattern:
                                break
                        read_elapsed = time.perf_counter() - read_start

                        for offset in range(0, erase_bytes, sector_size):
                            self._flash_sector_erase(dev, start_addr + offset, spi_flash)
                    finally:
                        dev.close()

                    mismatch_offset = next(
                        (
                            offset
                            for offset, (expected, actual) in enumerate(zip(pattern, readback))
                            if expected != actual
                        ),
                        None,
                    )
                    assert len(readback) == length, (
                        f"SPI flash readback returned {len(readback)}/{length} bytes"
                    )
                    assert mismatch_offset is None, (
                        f"Random-pattern mismatch at offset 0x{mismatch_offset:x}: "
                        f"expected 0x{pattern[mismatch_offset]:02x}, "
                        f"got 0x{readback[mismatch_offset]:02x}"
                    )

                    payload_bits = length * 8
                    program_bps = payload_bits / program_elapsed
                    read_bps = payload_bits * read_cycles / read_elapsed
                    summary = (
                        f"program {program_bps:.0f} bps, read {read_bps:.0f} bps "
                        f"over {read_cycles} cycles/{read_elapsed:.2f} s "
                        f"(expected >= {floor:.0f})"
                    )
                    if program_bps < floor or read_bps < floor:
                        pytest.fail(summary)
                    runner.add_detail(key, summary)

                runner.run(case_key, _one)

        runner.finish()

    def test_flash_write_read(self, board_cfg, lstp_channels, spidev_devices, request) -> None:
        """Erase one sector, write incrementing 32-bit values, then verify."""
        if spidev is None:
            pytest.skip("spidev python package not installed")
        flash_ids = self.get_spi_flash_ids(board_cfg)
        if not flash_ids:
            pytest.skip(self.NO_SPI_FLASH)

        runner = DeviceRunner(
            board_cfg,
            "spi",
            "flash_write_read",
            requires=[("spi", "spi_children", self._flash_parent_key)],
            request=request,
        )
        for flash_id in flash_ids:

            def _one(fid=flash_id) -> None:
                self._require_spidev_setup(spidev_devices)
                spi_flash = self.resolve_spi_flash(fid, board_cfg, lstp_channels, spidev_devices)
                page_size = spi_flash["page_size"]
                sector_size = spi_flash["sector_size"]
                addr = spi_flash["start_addr"]
                assert addr % sector_size == 0, (
                    f"SPI flash start_addr 0x{addr:x} must be sector-aligned"
                )
                assert 0 <= addr and addr + sector_size <= spi_flash["size"], (
                    f"SPI flash window 0x{addr:x}-0x{addr + sector_size:x} exceeds "
                    f"configured size 0x{spi_flash['size']:x}"
                )
                num_words = sector_size // 4
                base = int(time.time()) & 0xFFFFFFFF
                pattern = struct.pack(
                    f"<{num_words}I", *(((base + i) & 0xFFFFFFFF) for i in range(num_words))
                )
                dev = self._open_flash(spi_flash["spidev_path"], spi_flash)
                try:
                    self._flash_sector_erase(dev, addr, spi_flash)
                    erased = self._flash_read_data(dev, addr, sector_size, spi_flash)
                    not_ff = sum(1 for b in erased if b != 0xFF)
                    assert not_ff == 0, f"{not_ff}/{sector_size} SPI flash bytes not erased to 0xFF"
                    for off in range(0, sector_size, page_size):
                        self._flash_page_program(
                            dev, addr + off, pattern[off : off + page_size], spi_flash
                        )
                    readback = self._flash_read_data(dev, addr, sector_size, spi_flash)
                    assert len(readback) == sector_size, (
                        f"SPI flash readback returned {len(readback)}/{sector_size} bytes"
                    )
                finally:
                    dev.close()

                mismatches = []
                for i in range(num_words):
                    off = i * 4
                    expected = struct.pack("<I", (base + i) & 0xFFFFFFFF)
                    actual = readback[off : off + 4]
                    if actual != expected:
                        mismatches.append(
                            f"offset 0x{off:04x}: expected {expected.hex()} got {actual.hex()}"
                        )
                assert not mismatches, (
                    f"{len(mismatches)}/{num_words} SPI flash words mismatched:\n"
                    + "\n".join(mismatches[:20])
                )

            runner.run(flash_id, _one)
        runner.finish()

