#
# LED sysfs tests: brightness, blink, and pattern triggers.
#
# Board config: ``gpio`` section in boards/<board>.yaml
#   devices:            chip_label -> offset -> [line_name, input|output|led]
#   bandwidth:          expected_bandwidth (ops/s)
#   led_tick_period_ms: LedTickPeriodMs (firmware engine grid)
#   led_max_steps:      LedMaxStepsPerPattern (firmware-side cap)
# ``led`` rows must reject gpiod line requests (same EINVAL as ``gpioset``).
#
# Usage: --suite led

from __future__ import annotations

from collections.abc import Callable
import errno
import os
from pathlib import Path
import subprocess
import time

import pytest

import priv
from device_results import DeviceRunner, SUITE
from test_gpio import TestGpio

try:
    import gpiod
    from gpiod.line import Direction
except ImportError:
    gpiod = None


class TestLed:
    """LED sysfs class device: brightness, triggers, and pattern engine.

    ``test_led_devices_created`` / ``test_led_expected_sysfs`` gate the rest via
    per-LED results in ``board_cfg['_results']`` (one dependency branch per LED).
    """

    LEDS_ROOT = "/sys/class/leds"
    USB_LEDS_DIR = "leds"  # /sys/bus/usb/devices/<intf>/leds/<name>
    MAX_BRIGHTNESS = 255
    ON_GRID_TICKS = 25  # on_grid_ms = led_tick_period_ms * ON_GRID_TICKS
    OFF_GRID_OFFSET_MS = 2  # off_grid_ms = led_tick_period_ms + OFF_GRID_OFFSET_MS
    DEFAULT_BLINK_MS = 500  # lstp_led_blink_set when delay_on/off are both 0
    REPEAT_FOREVER = "-1"  # ledtrig-pattern ABI: -1 means play forever
    ERR_EINVAL = "Invalid argument"  # kernel-side rejection (e.g. repeat_store)
    ERR_EOPNOTSUPP = "Operation not supported"  # firmware rejection via lstp_led_set_pattern
    NO_DEVICES = "no LEDs in board YAML"

    @classmethod
    def get_expected_configs(cls, cfg: dict) -> dict:
        """Return LED devices and pattern-engine settings from ``gpio`` board config."""
        gpio = cfg.get("gpio", {}) or {}
        tick_ms = int(gpio.get("led_tick_period_ms", 5))
        return {
            "led_devices": {name: {} for name in cls.led_line_map(cfg)},
            "led_tick_period_ms": tick_ms,
            "led_max_steps": int(gpio.get("led_max_steps", 8)),
            "on_grid_ms": tick_ms * cls.ON_GRID_TICKS,
            "off_grid_ms": tick_ms + cls.OFF_GRID_OFFSET_MS,
        }

    @classmethod
    def led_line_map(cls, cfg: dict) -> dict[str, tuple[str, int]]:
        """Map LED sysfs name -> ``(gpio_chip_label, line_offset)`` from YAML ``led`` rows."""
        mapping: dict[str, tuple[str, int]] = {}
        for chip_label, lines in cfg["_gpio"]["expected_info"].items():
            for offset, line in lines.items():
                if line["kind"] == "led":
                    mapping[line["name"]] = (chip_label, offset)
        return mapping

    @classmethod
    def try_request_line(cls, chip_name: str, offset: int) -> int | None:
        """Return ``None`` if the line was requestable, else the rejection errno."""
        try:
            request = gpiod.request_lines(
                f"/dev/{chip_name}",
                consumer="lstp_qa_request",
                config={offset: gpiod.LineSettings(direction=Direction.AS_IS)},
            )
        except OSError as exc:
            return exc.errno
        except ValueError as exc:
            # gpiod 2.x raises ValueError(22, 'Invalid argument') for EINVAL.
            if exc.args and isinstance(exc.args[0], int):
                return exc.args[0]
            raise
        request.release()
        return None

    @classmethod
    def discover_usb_leds(cls, usb_sysfs: str) -> list[str]:
        """Return LED sysfs names registered under this LSTP USB interface."""
        leds_dir = os.path.join(usb_sysfs, cls.USB_LEDS_DIR)
        if not os.path.isdir(leds_dir):
            return []
        return sorted(
            name for name in os.listdir(leds_dir) if os.path.isdir(os.path.join(leds_dir, name))
        )

    @classmethod
    def modprobe_ledtrig_pattern(cls) -> None:
        """Load ``ledtrig-pattern`` or skip the current test."""
        try:
            priv.sudo_run(["modprobe", "ledtrig-pattern"])
        except (subprocess.CalledProcessError, OSError) as e:
            pytest.skip(f"cannot modprobe ledtrig-pattern: {e}")

    @classmethod
    def select_trigger_for_all(cls, leds: list[str], trigger: str) -> None:
        """Switch every LED in *leds* to *trigger*."""
        for led in leds:
            priv.sysfs_write(f"{cls.LEDS_ROOT}/{led}/trigger", f"{trigger}\n")

    @classmethod
    def clear_pattern_all(cls, leds: list[str]) -> None:
        """Empty ``hw_pattern`` on every LED that exposes it."""
        for name in leds:
            path = f"{cls.LEDS_ROOT}/{name}/hw_pattern"
            if os.path.isfile(path):
                priv.sysfs_write(path, "\n")

    @classmethod
    def reset_led(cls, name: str) -> None:
        """Park *name* in a known state: ``trigger=none``, ``brightness=0``."""
        priv.sysfs_write(f"{cls.LEDS_ROOT}/{name}/trigger", "none\n")
        priv.sysfs_write(f"{cls.LEDS_ROOT}/{name}/brightness", "0\n")

    def _run_pattern_variations(
        self,
        led_devices: list[str],
        cases: list[tuple[str, str, str | None]],
        attr: str,
        header: str,
        default_note: str,
        *,
        before_each_led: Callable[[], None] | None = None,
        after_accept: Callable[[str], str | None] | None = None,
    ) -> str:
        """Run *cases* against sysfs *attr*; return "" if all passed."""
        lines: list[str] = []
        for label, value, expect_err in cases:
            failures: dict[str, list[str]] = {}
            for name in led_devices:
                if before_each_led:
                    before_each_led()
                led_path = f"{self.LEDS_ROOT}/{name}"
                try:
                    priv.sysfs_write(f"{led_path}/{attr}", f"{value}\n")
                    err = None
                except OSError as e:
                    err = e.strerror
                msg = ""
                if expect_err is None and err is None:
                    if after_accept:
                        msg = after_accept(name) or ""
                elif expect_err is None:
                    msg = "Unexpectedly rejected"
                elif err is None:
                    msg = "Unexpectedly accepted"
                elif expect_err not in err:
                    msg = "Wrong errno"
                if msg:
                    failures.setdefault(msg, []).append(name)
            for msg, leds in failures.items():
                lines.append(f"Case {label} ({attr}={value!r}): {msg}: {leds}")
        if not lines:
            return ""
        return f"{header}, default value: {default_note}\n  " + "\n  ".join(lines)

    def pattern_set_repeat_variations(self, led_cfg: dict, led_devices: list[str]) -> str:
        """LSTP ``repeat`` field. Accepted values chain into ``hw_pattern``."""
        on_grid_ms = led_cfg["on_grid_ms"]
        good_pattern = f"{self.MAX_BRIGHTNESS} {on_grid_ms} 0 {on_grid_ms}"
        tick_ms = led_cfg["led_tick_period_ms"]

        def chain_pattern(name: str) -> str | None:
            try:
                priv.sysfs_write(f"{self.LEDS_ROOT}/{name}/hw_pattern", f"{good_pattern}\n")
            except OSError:
                return "Pattern set chain failed"
            return None

        # (label, repeat, expect_err)
        cases = [
            ("forever", self.REPEAT_FOREVER, None),
            ("once", "1", None),
            ("many", "3", None),
            ("zero", "0", self.ERR_EINVAL),
            ("negative", "-2", self.ERR_EINVAL),
        ]
        return self._run_pattern_variations(
            led_devices,
            cases,
            "repeat",
            "[repeat]",
            f"pattern={good_pattern!r}",
            before_each_led=lambda: time.sleep(tick_ms / 1000.0),
            after_accept=chain_pattern,
        )

    def _prime_repeat_forever(self, led_devices: list[str]) -> list[str]:
        """Set ``repeat=-1`` on each LED; return per-LED setup failure lines."""
        failures: list[str] = []
        for name in led_devices:
            try:
                priv.sysfs_write(f"{self.LEDS_ROOT}/{name}/repeat", f"{self.REPEAT_FOREVER}\n")
            except OSError as e:
                failures.append(f"{name}: repeat setup failed: {e}")
        return failures

    def pattern_set_num_steps_variations(self, led_cfg: dict, led_devices: list[str]) -> str:
        """LSTP ``num_steps`` field via ``hw_pattern``."""
        on_grid_ms = led_cfg["on_grid_ms"]
        max_steps = led_cfg["led_max_steps"]
        mx = self.MAX_BRIGHTNESS
        step_off = f"0 {on_grid_ms * 2}"
        step_on = f"{mx} {on_grid_ms}"

        def make_pattern(n: int) -> str:
            return " ".join(step_off if i % 2 == 0 else step_on for i in range(n))

        if failures := self._prime_repeat_forever(led_devices):
            header = f"[num_steps], default value: repeat={self.REPEAT_FOREVER}\n  "
            return header + "\n  ".join(failures)
        # (label, pattern, expect_err)
        cases = [
            ("one_hold_zero", f"{mx} 0", None),
            ("one_hold_pos", f"{mx // 2} {on_grid_ms}", None),
            ("multi", make_pattern(max_steps - 1), None),
            (f"max_{max_steps}", make_pattern(max_steps), None),
            (f"over_{max_steps + 1}", make_pattern(max_steps + 1), self.ERR_EOPNOTSUPP),
        ]
        return self._run_pattern_variations(
            led_devices, cases, "hw_pattern", "[num_steps]", f"repeat={self.REPEAT_FOREVER}"
        )

    def pattern_set_time_ms_variations(self, led_cfg: dict, led_devices: list[str]) -> str:
        """LSTP ``time_ms`` field via ``hw_pattern``."""
        on_grid_ms = led_cfg["on_grid_ms"]
        off_grid_ms = led_cfg["off_grid_ms"]
        mx = self.MAX_BRIGHTNESS

        if failures := self._prime_repeat_forever(led_devices):
            header = f"[time_ms], default value: repeat={self.REPEAT_FOREVER}\n  "
            return header + "\n  ".join(failures)
        # (label, pattern, expect_err)
        cases = [
            ("positive_ongrid", f"{mx} {on_grid_ms * 4} 0 {on_grid_ms * 8}", None),
            ("zero_then_positive", f"{mx} 0 0 {on_grid_ms * 8}", None),
            ("all_zero", f"{mx} 0 0 0", self.ERR_EOPNOTSUPP),
            ("offgrid", f"{mx} {off_grid_ms} 0 {off_grid_ms}", self.ERR_EOPNOTSUPP),
        ]
        return self._run_pattern_variations(
            led_devices, cases, "hw_pattern", "[time_ms]", f"repeat={self.REPEAT_FOREVER}"
        )

    def _run_each_led(
        self,
        board_cfg,
        test_name,
        requires,
        led_names: list[str],
        fn: Callable[[str], None],
        request=None,
    ) -> DeviceRunner:
        """Run *fn(led_name)* once per LED with independent dependency tracking."""
        runner = DeviceRunner(
            board_cfg,
            "led",
            test_name,
            requires=None if not led_names else requires,
            skip=self.NO_DEVICES,
            request=request,
        )
        for name in led_names:
            runner.run(name, lambda n=name: fn(n))
        return runner

    # ------------------------- LED Tests -------------------------

    def test_led_devices_created(self, board_cfg, usb_sysfs, led_devices, request) -> None:
        """Verify every configured ``led`` row under USB and class LED sysfs.

        Each row must exist under ``<usb>/leds/<name>`` and
        ``/sys/class/leds/<name>``; pin names are checked on the gpiochip separately.
        """
        runner = DeviceRunner(
            board_cfg, "led", "led_devices_created", skip=self.NO_DEVICES, request=request
        )
        if not led_devices:
            runner.finish()
            return

        leds_dir = os.path.join(usb_sysfs, self.USB_LEDS_DIR)
        found = set(self.discover_usb_leds(usb_sysfs)) if os.path.isdir(leds_dir) else set()

        for name in led_devices:

            def _one(n=name) -> None:
                if not os.path.isdir(leds_dir):
                    raise AssertionError(f"Missing LED directory {leds_dir}")
                usb_path = os.path.join(leds_dir, n)
                assert n in found, f"expected at '{usb_path}'"
                class_path = os.path.join(self.LEDS_ROOT, n)
                assert os.path.isdir(class_path), f"expected at '{class_path}'"

            runner.run(name, _one)

        unexpected = sorted(found - set(led_devices))
        if unexpected:
            runner.failed(SUITE, "Unexpected: [" + ", ".join(unexpected) + "]")
        runner.finish()

    def test_led_expected_sysfs(self, board_cfg, led_devices, request) -> None:
        """Verify every configured LED exposes required sysfs attributes.

        Each LED must expose ``brightness``, ``trigger``, and ``max_brightness == 255``.
        """

        def _one(name: str) -> None:
            issues: list[str] = []
            d = os.path.join(self.LEDS_ROOT, name)
            if not os.path.isdir(d):
                issues.append(f"Missing '{d}'")
            else:
                missing_attrs = [
                    attr
                    for attr in ("brightness", "trigger", "max_brightness")
                    if not os.path.isfile(os.path.join(d, attr))
                ]
                if missing_attrs:
                    issues.append(f"Missing attrs {missing_attrs!r}")
                else:
                    raw = Path(self.LEDS_ROOT, name, "max_brightness").read_text().strip()
                    try:
                        actual_max = int(raw)
                    except ValueError:
                        issues.append(f"Mismatched max_brightness (not an integer: {raw!r})")
                    else:
                        if actual_max != self.MAX_BRIGHTNESS:
                            issues.append(
                                "Mismatched max_brightness "
                                f"(expected '{self.MAX_BRIGHTNESS}', got '{actual_max}')"
                            )
            assert not issues, ", ".join(issues)

        self._run_each_led(
            board_cfg,
            "led_expected_sysfs",
            [("led", "led_devices_created")],
            led_devices,
            _one,
            request=request,
        ).finish()

    def test_led_not_gpio(self, board_cfg, led_devices, gpio_chips, request) -> None:
        """``led`` rows must reject gpiod requests with EINVAL (``gpioset``/``gpioget``)."""
        line_map = self.led_line_map(board_cfg)

        def _one(name: str) -> None:
            if gpiod is None:
                pytest.skip("python3-gpiod not installed")
            chip_label, off = line_map[name]
            assert chip_label in gpio_chips, f"{chip_label}: GPIO chip not found"
            err = self.try_request_line(gpio_chips[chip_label], off)
            if err is None:
                raise AssertionError(f"line {off} (expected 'EINVAL', got 'requestable')")
            if err != errno.EINVAL:
                raise AssertionError(f"line {off} (expected 'EINVAL', got errno {err})")

        self._run_each_led(
            board_cfg,
            "led_not_gpio",
            [("led", "led_devices_created")],
            led_devices,
            _one,
            request=request,
        ).finish()

    def test_led_brightness_set_blocking(self, board_cfg, led_devices, led_reset, request) -> None:
        """Verify blocking brightness writes via ``lstp_led_brightness_set_blocking``.

        ``echo N > brightness`` round-trips; over-max writes are clamped by the LED core.
        """
        mx = self.MAX_BRIGHTNESS
        cases = [
            ("0", "0"),
            (str(mx // 2), str(mx // 2)),
            (str(mx), str(mx)),
            (str(mx + 1), str(mx)),
        ]

        def _one(name: str) -> None:
            brightness_path = f"{self.LEDS_ROOT}/{name}/brightness"
            problems: list[str] = []
            for wr, expected in cases:
                try:
                    priv.sysfs_write(brightness_path, f"{wr}\n")
                    rd = Path(brightness_path).read_text().strip()
                except OSError as e:
                    problems.append(f"wrote={wr}, I/O error: {e}")
                    continue
                if rd != expected:
                    problems.append(f"wrote={wr}, readback={rd}, expected={expected}")
            assert not problems, "Brightness round-trip failures:\n  " + "\n  ".join(problems)

        self._run_each_led(
            board_cfg,
            "led_brightness_set_blocking",
            [("led", "led_expected_sysfs")],
            led_devices,
            _one,
            request=request,
        ).finish()

    def test_led_blink_set(self, board_cfg, led_devices, led_reset, request) -> None:
        """Verify timer-trigger blink delays via ``lstp_led_blink_set``.

        ``delay_on``/``delay_off`` of 0/0 are accepted and default to 500 ms.
        """
        led_cfg = self.get_expected_configs(board_cfg)
        tick_ms = led_cfg["led_tick_period_ms"]
        on_grid_ms = led_cfg["on_grid_ms"]
        cases = [
            ("asymmetric", str(on_grid_ms * 2), str(on_grid_ms)),
            ("solid_on", str(on_grid_ms), "0"),
            ("solid_off", "0", str(on_grid_ms)),
            ("floor", str(tick_ms), str(tick_ms)),
            ("both_zero", "0", "0"),
        ]

        def _one(name: str) -> None:
            lines: list[str] = []
            led_dir = f"{self.LEDS_ROOT}/{name}"
            for label, delay_on, delay_off in cases:
                try:
                    priv.sysfs_write(f"{led_dir}/trigger", "timer\n")
                    priv.sysfs_write(f"{led_dir}/delay_off", f"{delay_off}\n")
                    priv.sysfs_write(f"{led_dir}/delay_on", f"{delay_on}\n")
                except OSError:
                    lines.append(
                        f"Case {label} (delay_on={delay_on}, delay_off={delay_off}): "
                        "Sysfs write failed"
                    )
                    continue
                try:
                    rd_on = Path(led_dir, "delay_on").read_text().strip()
                    rd_off = Path(led_dir, "delay_off").read_text().strip()
                except OSError:
                    lines.append(
                        f"Case {label} (delay_on={delay_on}, delay_off={delay_off}): "
                        "Delay readback failed"
                    )
                    continue
                if label == "both_zero":
                    expect = str(self.DEFAULT_BLINK_MS)
                    if rd_on != expect or rd_off != expect:
                        lines.append(
                            f"Case {label} (delay_on={delay_on}, delay_off={delay_off}): "
                            f"Delay readback={rd_on}/{rd_off}, expected={expect}/{expect}"
                        )
                elif rd_on != delay_on or rd_off != delay_off:
                    lines.append(
                        f"Case {label} (delay_on={delay_on}, delay_off={delay_off}): "
                        f"Delay readback={rd_on}/{rd_off}, expected={delay_on}/{delay_off}"
                    )
            assert not lines, "[Blink_set], default value: trigger=timer\n  " + "\n  ".join(lines)

        self._run_each_led(
            board_cfg,
            "led_blink_set",
            [("led", "led_brightness_set_blocking")],
            led_devices,
            _one,
            request=request,
        ).finish()

    def test_led_pattern_clear(self, board_cfg, led_devices, led_reset, request) -> None:
        """Verify empty ``hw_pattern`` writes clear a prior pattern.

        Accepted only after a prior pattern was written.
        """
        if led_devices:
            self.modprobe_ledtrig_pattern()
        on_grid_ms = self.get_expected_configs(board_cfg)["on_grid_ms"]

        def _one(name: str) -> None:
            self.select_trigger_for_all([name], "pattern")
            try:
                priv.sysfs_write(f"{self.LEDS_ROOT}/{name}/repeat", f"{self.REPEAT_FOREVER}\n")
                priv.sysfs_write(
                    f"{self.LEDS_ROOT}/{name}/hw_pattern",
                    f"{self.MAX_BRIGHTNESS} {on_grid_ms} 0 {on_grid_ms}\n",
                )
            except OSError as e:
                raise AssertionError(f"Setup failed: {e}") from e
            try:
                priv.sysfs_write(f"{self.LEDS_ROOT}/{name}/hw_pattern", "\n")
            except OSError as e:
                raise AssertionError(f"Clear failed: {e}") from e

        self._run_each_led(
            board_cfg,
            "led_pattern_clear",
            [("led", "led_expected_sysfs")],
            led_devices,
            _one,
            request=request,
        ).finish()

    def test_led_pattern_set(self, board_cfg, led_devices, led_reset, request) -> None:
        """Exercise LSTP pattern fields via ``hw_pattern``.

        Covers ``repeat``, ``num_steps``, and ``time_ms`` under pattern trigger
        (``lstp_led_pattern_set``; ``pattern`` would hit the kernel's SW blink loop).
        """
        if led_devices:
            self.modprobe_ledtrig_pattern()
        led_cfg = self.get_expected_configs(board_cfg)

        def _one(name: str) -> None:
            triggers = [
                t.strip("[]") for t in Path(self.LEDS_ROOT, name, "trigger").read_text().split()
            ]
            assert "pattern" in triggers, "Sysfs .../<led_name>/trigger missing 'pattern'"
            self.select_trigger_for_all([name], "pattern")
            assert os.path.isfile(os.path.join(self.LEDS_ROOT, name, "hw_pattern")), (
                "Sysfs .../<led_name>/hw_pattern missing"
            )
            leds = [name]
            blocks = [
                self.pattern_set_repeat_variations(led_cfg, leds),
                self.pattern_set_num_steps_variations(led_cfg, leds),
                self.pattern_set_time_ms_variations(led_cfg, leds),
            ]
            blocks = [b for b in blocks if b]
            assert not blocks, "Pattern set variations:\n" + "\n\n".join(blocks)

        self._run_each_led(
            board_cfg,
            "led_pattern_set",
            [("led", "led_pattern_clear")],
            led_devices,
            _one,
            request=request,
        ).finish()

    def test_led_pattern_replace_mid_cycle(
        self, board_cfg, led_devices, led_reset, request
    ) -> None:
        """A new pattern written mid-cycle replaces the running one cleanly."""
        led_cfg = self.get_expected_configs(board_cfg)
        on_grid_ms = led_cfg["on_grid_ms"]
        slow_ms = on_grid_ms * 16
        mx = self.MAX_BRIGHTNESS
        pattern = f"{mx} {on_grid_ms} 0 {on_grid_ms}"

        def _one(name: str) -> None:
            self.select_trigger_for_all([name], "pattern")
            try:
                priv.sysfs_write(f"{self.LEDS_ROOT}/{name}/repeat", f"{self.REPEAT_FOREVER}\n")
                priv.sysfs_write(
                    f"{self.LEDS_ROOT}/{name}/hw_pattern", f"{mx} {slow_ms} 0 {slow_ms}\n"
                )
            except OSError as e:
                raise AssertionError(
                    f"Initial pattern setup failed: {e}; skipping mid-cycle replace"
                ) from e
            time.sleep(0.5)
            try:
                priv.sysfs_write(f"{self.LEDS_ROOT}/{name}/hw_pattern", f"{pattern}\n")
                readback = Path(self.LEDS_ROOT, name, "hw_pattern").read_text().strip()
            except OSError as e:
                raise AssertionError(f"Mid-cycle pattern write failed: {e}") from e
            assert readback == pattern, (
                f"pattern not properly applied (readback={readback!r}, expected={pattern!r})"
            )
            time.sleep(0.3)

        self._run_each_led(
            board_cfg,
            "led_pattern_replace_mid_cycle",
            [("led", "led_pattern_set")],
            led_devices,
            _one,
            request=request,
        ).finish()

