#
# GPIO enumeration, toggle, and bandwidth tests.
#
# Board config: ``gpio`` section in boards/<board>.yaml
#   devices:   chip_label -> offset -> [line_name, input|output|led]
#   bandwidth: expected bandwidth (ops/s; latency threshold derived as 1e6/ops µs/op)
#
# Usage: --suite gpio
# IRQ tests live in ``test_irq.py`` and LED tests live in ``test_led.py``.

from __future__ import annotations

from functools import partial
import os
from pathlib import Path
import random
import re
import statistics
import subprocess
import time

import pytest

from device_results import DeviceRunner

try:
    import gpiod
    from gpiod.line import Direction, Value
except ImportError:
    gpiod = None


class TestGpio:
    """GPIO chips and lines vs board YAML."""

    # lstp-gpio.c LED pins show as input consumer="kernel" in gpioinfo.
    LED_GPIOINFO_DIRECTION = 'input consumer="kernel"'

    # gpiod v1:  line 0: "GPIO_00"  unused  input  active-high
    # gpiod v2:  line 0: "GPIO_00"  input
    #            line 5: "led0"     output consumer="kernel"
    GPIOINFO_LINE_RE = re.compile(
        r'^\s*line\s+(\d+):\s*(?:"([^"]*)"|(\S+))\s+'
        r"(?:(?!input\b|output\b)\S+\s+)?"
        r'((?:input|output)(?:\s+consumer="[^"]*")?)'
    )

    NO_DEVICES = "no gpio.devices in board YAML"
    DISCOVERY_SKIP = "GPIO device not discovered (see test_expected_gpiochips)"

    TOGGLE_CYCLES = 500
    BW_CYCLES = 500
    BW_WARMUP = 10
    SUBPROCESS_TIMEOUT_S = 30

    @classmethod
    def _run(cls, cmd: list[str], **kwargs) -> subprocess.CompletedProcess[str]:
        kwargs.setdefault("timeout", cls.SUBPROCESS_TIMEOUT_S)
        return subprocess.run(cmd, capture_output=True, text=True, check=True, **kwargs)

    @classmethod
    def get_expected_configs(cls, cfg: dict) -> dict:
        """Return ``cfg['gpio']['devices']``; build ``cfg['_gpio']`` once (session fixture):
        cfg['_gpio']
        ├── pin_lists # for toggle / bandwidth tests (non-led)
        │   └── <chip>
        │       ├── gpio: [input + output offsets]
        │       └── outputs: [output offsets]
        └── expected_info # gpioinfo (+ LED kind)
            └── <chip>
                └── <offset>: {name, kind, direction}
                    kind: gpio | led
                    direction: input | output | 'input consumer="kernel"'
        """
        devices = cfg.get("gpio", {}).get("devices", {}) or {}
        if "_gpio" in cfg:
            return devices

        pin_lists: dict[str, dict[str, list[int]]] = {}
        expected_info: dict[str, dict[int, dict[str, str]]] = {}
        for chip_label, rows in devices.items():
            gpios, outputs, lines = [], [], {}
            for offset, (name, direction) in sorted(rows.items(), key=lambda kv: int(kv[0])):
                direction = str(direction).strip().lower()
                offset_i = int(offset)
                if direction in ("input", "output"):
                    gpios.append(offset_i)
                    if direction == "output":
                        outputs.append(offset_i)
                    kind, gpioinfo_direction = "gpio", direction
                elif direction == "led":
                    kind, gpioinfo_direction = "led", cls.LED_GPIOINFO_DIRECTION
                else:
                    raise ValueError(f"Invalid pin direction {direction!r} at offset {offset_i}")
                lines[offset_i] = {"name": name, "kind": kind, "direction": gpioinfo_direction}
            pin_lists[chip_label] = {"gpio": gpios, "outputs": outputs}
            expected_info[chip_label] = lines

        cfg["_gpio"] = {"pin_lists": pin_lists, "expected_info": expected_info}
        return devices

    @classmethod
    def expected_gpioinfo(cls, cfg: dict, chip_label: str) -> dict[int, dict[str, str]]:
        """Return expected gpioinfo fields for *chip_label* from ``cfg['_gpio']``."""
        return cfg["_gpio"]["expected_info"].get(chip_label, {})

    @classmethod
    def chip_pins(cls, cfg: dict, chip_label: str) -> dict[str, list[int]]:
        """Return ``{gpio, outputs}`` for *chip_label* from ``cfg['_gpio']``."""
        return cfg["_gpio"]["pin_lists"][chip_label]

    @classmethod
    def min_ops_per_s(cls, cfg: dict) -> int:
        """Return the YAML ``gpio.bandwidth`` floor in ops/s (0 if unset)."""
        raw = cfg.get("gpio", {}).get("bandwidth")
        if raw in (None, ""):
            return 0
        try:
            min_ops = int(raw)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"gpio.bandwidth must be an integer, got {raw!r}") from exc
        if min_ops < 0:
            raise ValueError(f"gpio.bandwidth must be >= 0, got {min_ops}")
        return min_ops

    @classmethod
    def actual_gpioinfo(cls, chip_name: str) -> dict[int, dict[str, str]]:
        """Run ``gpioinfo`` on *chip_name* (gpiod v1/v2), as ``{offset: {name, direction}}``."""
        try:
            output = cls._run(["gpioinfo", "-c", chip_name]).stdout
        except FileNotFoundError:
            pytest.skip("gpioinfo not installed")
        except subprocess.TimeoutExpired as err1:
            pytest.fail(f"gpioinfo timed out with -c after {err1.timeout}s")
        except subprocess.CalledProcessError as err1:
            try:
                output = cls._run(["gpioinfo", chip_name]).stdout
            except FileNotFoundError:
                pytest.skip("gpioinfo not installed")
            except subprocess.TimeoutExpired as err2:
                pytest.fail(f"gpioinfo fallback timed out after {err2.timeout}s")
            except subprocess.CalledProcessError as err2:
                pytest.fail(
                    f"gpioinfo failed for {chip_name!r}:"
                    f" -c stderr={err1.stderr!r}, fallback stderr={err2.stderr!r}"
                )
        lines: dict[int, dict[str, str]] = {}
        for line in output.splitlines():
            m = cls.GPIOINFO_LINE_RE.match(line)
            if not m:
                continue
            lines[int(m.group(1))] = {"name": m.group(2) or m.group(3), "direction": m.group(4)}
        return lines

    @classmethod
    def diff_gpioinfo(
        cls, expected: dict[int, dict[str, str]], actual: dict[int, dict[str, str]], field: str
    ) -> tuple[list[str], list[str]]:
        """Compare ``expected_gpioinfo`` vs ``actual_gpioinfo`` on *field*."""
        mismatched = [
            (
                f"line {offset} (expected "
                f"'{expected[offset].get(field)}', "
                f"got '{actual.get(offset, {}).get(field)}')"
            )
            for offset in sorted(expected)
            if expected[offset].get(field) != actual.get(offset, {}).get(field)
        ]
        unexpected = [
            f"line {offset} ('{actual[offset].get(field)}')"
            for offset in sorted(set(actual) - set(expected))
        ]
        return mismatched, unexpected

    @classmethod
    def _request_lines(cls, chip_name: str, offsets: list[int], consumer: str):
        """Request *offsets* with AS_IS settings, or return ``None`` on failure."""
        try:
            return gpiod.request_lines(
                f"/dev/{chip_name}",
                consumer=consumer,
                config={
                    offset: gpiod.LineSettings(direction=Direction.AS_IS) for offset in offsets
                },
            )
        except OSError:
            return None

    @classmethod
    def toggle_patterns(
        cls, chip_name: str, offsets: list[int], cycles: int, *, randomize: bool = False
    ) -> tuple[int, int] | None:
        """Write *cycles* patterns via multi ``set_values`` / ``get_values``; verify readback.

        With ``randomize=False``, every pin flips 0 <-> 1 each cycle (cycle 0 = ACTIVE).
        With ``randomize=True``, each cycle draws ``random.getrandbits(N)``
        (``offsets[0]`` = LSB). Returns ``None`` if the lines could not be requested.
        """
        if not offsets:
            return 0, 0
        request = cls._request_lines(chip_name, offsets, "lstp_qa_toggle")
        if request is None:
            return None
        try:
            write_errors = readback_errors = 0
            pin_count = len(offsets)
            for cycle in range(cycles):
                if randomize:
                    mask = random.getrandbits(pin_count)
                    want = [
                        Value.ACTIVE if (mask >> i) & 1 else Value.INACTIVE
                        for i in range(pin_count)
                    ]
                else:
                    bit = Value.ACTIVE if cycle % 2 == 0 else Value.INACTIVE
                    want = [bit] * pin_count
                try:
                    request.set_values(dict(zip(offsets, want)))
                except OSError:
                    write_errors += 1
                    continue
                try:
                    if request.get_values(offsets) != want:
                        readback_errors += 1
                except OSError:
                    readback_errors += 1
            return write_errors, readback_errors
        finally:
            request.release()

    @staticmethod
    def _toggle_failure(scope: str, result: tuple[int, int] | None, cycles: int) -> str | None:
        """Format a toggle failure line, or ``None`` when the run was clean."""
        if result is None:
            return f"{scope}: could not request line(s)"
        write_errors, readback_errors = result
        parts = []
        if write_errors:
            parts.append(f"{write_errors}/{cycles} writes failed")
        if readback_errors:
            parts.append(f"{readback_errors}/{cycles} readbacks mismatched")
        return f"{scope}: {', '.join(parts)}" if parts else None

    @staticmethod
    def _format_mean_ops(mean_ops: float, label: str | None = None) -> str:
        """Mean ops/s line for PASSED detail / multichannel (optional ``label:`` prefix)."""
        detail = f"{mean_ops:.0f} ops/s ({1_000_000 / mean_ops:.0f} µs/op)"
        return f"{label}: {detail}" if label else detail

    @classmethod
    def _bw_stats_body(cls, stats: tuple[float, int, float, int, float]) -> str:
        """Full min/mean/max ops/s for FAILED pin lines (expected floor is the header)."""
        min_ops, min_cyc, max_ops, max_cyc, mean_ops = stats
        return (
            f"mean={mean_ops:.0f} ops/s ({1_000_000 / mean_ops:.1f} µs/op), "
            f"min={min_ops:.0f} ops/s ({1_000_000 / min_ops:.1f} µs/op, cycle {min_cyc}), "
            f"max={max_ops:.0f} ops/s ({1_000_000 / max_ops:.1f} µs/op, cycle {max_cyc})"
        )

    @classmethod
    def _bw_stats_from_samples(
        cls, samples: list[int], *, pins_per_op: int = 1
    ) -> tuple[float, int, float, int, float]:
        """Convert per-call latency samples (ns) to pin-ops/s ``(min, min_i, max, max_i, mean)``."""
        slowest = max(range(len(samples)), key=lambda i: samples[i])
        fastest = min(range(len(samples)), key=lambda i: samples[i])
        mean_ns = statistics.mean(samples)

        def _ops(ns: float) -> float:
            return float("inf") if ns == 0 else pins_per_op * 1_000_000_000 / ns

        return _ops(samples[slowest]), slowest, _ops(samples[fastest]), fastest, _ops(mean_ns)

    @classmethod
    def measure_bw(
        cls, chip_name: str, offset: int, cycles: int, warmup: int, *, write: bool
    ) -> tuple[float, int, float, int, float] | None:
        """Measure single-pin bandwidth in ops/s (one op = one pin read or write)."""
        offsets = [offset]
        request = cls._request_lines(
            chip_name, offsets, "lstp_qa_bw_wr" if write else "lstp_qa_bw_rd"
        )
        if request is None:
            return None
        try:
            value = Value.INACTIVE
            samples: list[int] = []
            for i in range(warmup + cycles):
                t0 = time.perf_counter_ns()
                try:
                    if write:
                        value = Value.ACTIVE if value == Value.INACTIVE else Value.INACTIVE
                        request.set_values({offset: value})
                    else:
                        request.get_values(offsets)
                except OSError:
                    return None
                if i >= warmup:
                    samples.append(time.perf_counter_ns() - t0)
            return cls._bw_stats_from_samples(samples)
        except OSError:
            return None
        finally:
            request.release()

    def _run_per_chip(
        self,
        board_cfg,
        gpio_chips,
        request,
        test_name: str,
        one,
        *,
        requires=None,
        need_gpiod: bool = False,
    ) -> None:
        """DeviceRunner over each YAML chip; *one(label, chip_name, runner)* does the assert."""
        if need_gpiod and gpiod is None:
            pytest.skip("python3-gpiod not installed")
        runner = DeviceRunner(
            board_cfg,
            "gpio",
            test_name,
            requires=requires or [],
            skip=self.NO_DEVICES,
            request=request,
        )
        for device_label in board_cfg.get("gpio", {}).get("devices", {}) or {}:
            runner.run(
                device_label,
                partial(one, device_label, gpio_chips[device_label], runner),
                when=device_label in gpio_chips,
                skip=self.DISCOVERY_SKIP,
            )
        runner.finish()

    def _run_bandwidth_suite(self, board_cfg, gpio_chips, request, *, write: bool) -> None:
        """Single-pin write/read bandwidth over ``outputs`` / ``gpio`` pin lists."""
        min_ops_per_s = self.min_ops_per_s(board_cfg)
        pin_key = "outputs" if write else "gpio"
        kind = "write" if write else "read"
        row = "output" if write else "gpio"

        def _one(label: str, chip_name: str, runner) -> None:
            pins = self.chip_pins(board_cfg, label)[pin_key]
            if not pins:
                pytest.skip(f"no {row} rows for {label} in board YAML")
            failures: list[str] = []
            means: list[float] = []
            for offset in pins:
                result = self.measure_bw(
                    chip_name, offset, self.BW_CYCLES, self.BW_WARMUP, write=write
                )
                if result is None:
                    failures.append(
                        f"line {offset}: bandwidth measurement failed (request or GPIO I/O error)"
                    )
                    continue
                *_, mean_ops = result
                means.append(mean_ops)
                if min_ops_per_s and mean_ops < min_ops_per_s:
                    failures.append(f"line {offset}: {self._bw_stats_body(result)}")
            if failures:
                head = [f"expected >= {min_ops_per_s} ops/s"] if min_ops_per_s else []
                pytest.fail("\n".join(head + failures))
            detail = self._format_mean_ops(sum(means) / len(means))
            if min_ops_per_s:
                detail += f", expected >= {min_ops_per_s} ops/s"
            runner.add_detail(label, detail)

        self._run_per_chip(
            board_cfg,
            gpio_chips,
            request,
            f"gpio_{kind}_bandwidth",
            _one,
            requires=[("gpio", "gpio_line_directions")],
            need_gpiod=True,
        )

    # ------------------------- GPIO Tests -------------------------

    def test_expected_gpiochips(self, board_cfg, gpio_chips) -> None:
        """Discovered GPIO chip labels must match board YAML exactly."""
        expected = set(board_cfg.get("gpio", {}).get("devices", {}) or {})
        discovered = set(gpio_chips)
        assert discovered == expected, (
            "GPIO chip labels must match board YAML exactly.\n"
            f"Missing: {sorted(expected - discovered)!r}\n"
            f"Unexpected: {sorted(discovered - expected)!r}"
        )

    def test_gpio_line_count(self, board_cfg, gpio_chips, request) -> None:
        """Gpiochip must expose every pin in board YAML (gpio and led rows)."""

        def _one(label: str, chip_name: str, _runner) -> None:
            expected = self.expected_gpioinfo(board_cfg, label)
            actual = self.actual_gpioinfo(chip_name)
            assert len(actual) == len(expected), (
                f"Expected {len(expected)} lines, got {len(actual)}"
            )
            ngpio_path = os.path.join("/sys/bus/gpio/devices", chip_name, "ngpio")
            if os.path.isfile(ngpio_path):
                ngpio = int(Path(ngpio_path).read_text().strip())
                assert len(expected) == ngpio, (
                    f"YAML lists {len(expected)} pins, chip ngpio={ngpio}"
                )

        self._run_per_chip(board_cfg, gpio_chips, request, "gpio_line_count", _one)

    def test_gpio_line_names(self, board_cfg, gpio_chips, request) -> None:
        """All ``pin_names`` on the gpiochip (gpio and led rows) must match gpioinfo."""

        def _one(label: str, chip_name: str, _runner) -> None:
            mismatched, unexpected = self.diff_gpioinfo(
                self.expected_gpioinfo(board_cfg, label), self.actual_gpioinfo(chip_name), "name"
            )
            assert not mismatched and not unexpected, (
                "GPIO chip line names must match board YAML exactly.\n"
                "Mismatched:\n" + "\n".join(f"  {m}" for m in mismatched) + "\n"
                "Unexpected:\n" + "\n".join(f"  {u}" for u in unexpected)
            )

        self._run_per_chip(
            board_cfg,
            gpio_chips,
            request,
            "gpio_line_names",
            _one,
            requires=[("gpio", "gpio_line_count")],
        )

    def test_gpio_line_directions(self, board_cfg, gpio_chips, request) -> None:
        """Gpioinfo direction must match board YAML; ``led`` rows expect kernel consumer."""

        def _one(label: str, chip_name: str, _runner) -> None:
            expected = self.expected_gpioinfo(board_cfg, label)
            actual = self.actual_gpioinfo(chip_name)
            expected_gpio = {
                offset: line for offset, line in expected.items() if line["kind"] == "gpio"
            }
            expected_led = {
                offset: line for offset, line in expected.items() if line["kind"] == "led"
            }
            mismatched_gpio, _ = self.diff_gpioinfo(expected_gpio, actual, "direction")
            mismatched_led, _ = self.diff_gpioinfo(expected_led, actual, "direction")
            assert not mismatched_gpio and not mismatched_led, (
                "GPIO line directions must match board YAML for gpio rows "
                f"and LED rows must appear as {self.LED_GPIOINFO_DIRECTION!r}.\n"
                "GPIO mismatched:\n" + "\n".join(f"  {m}" for m in mismatched_gpio) + "\n"
                "LED mismatched:\n" + "\n".join(f"  {m}" for m in mismatched_led)
            )

        self._run_per_chip(
            board_cfg,
            gpio_chips,
            request,
            "gpio_line_directions",
            _one,
            requires=[("gpio", "gpio_line_count")],
        )

    def test_gpio_toggle(self, board_cfg, gpio_chips, request) -> None:
        """Toggle each output alone, then random multi patterns on all outputs."""

        def _one(label: str, chip_name: str, _runner) -> None:
            outputs = self.chip_pins(board_cfg, label)["outputs"]
            if not outputs:
                pytest.skip(f"no gpio output rows for {label} in board YAML")
            failures: list[str] = []
            for offset in outputs:
                detail = self._toggle_failure(
                    f"line {offset}",
                    self.toggle_patterns(chip_name, [offset], self.TOGGLE_CYCLES),
                    self.TOGGLE_CYCLES,
                )
                if detail:
                    failures.append(detail)
            detail = self._toggle_failure(
                f"all outputs ({len(outputs)})",
                self.toggle_patterns(chip_name, outputs, self.TOGGLE_CYCLES, randomize=True),
                self.TOGGLE_CYCLES,
            )
            if detail:
                failures.append(detail)
            assert not failures, "Toggle failures:\n" + "\n".join(failures)

        self._run_per_chip(
            board_cfg,
            gpio_chips,
            request,
            "gpio_toggle",
            _one,
            requires=[("gpio", "gpio_line_directions")],
            need_gpiod=True,
        )

    def test_gpio_write_bandwidth(self, board_cfg, gpio_chips, request) -> None:
        """Write bandwidth for every ``gpio`` output row (``gpio.bandwidth`` floor)."""
        self._run_bandwidth_suite(board_cfg, gpio_chips, request, write=True)

    def test_gpio_read_bandwidth(self, board_cfg, gpio_chips, request) -> None:
        """Read bandwidth for every ``gpio`` row (``gpio.bandwidth`` floor)."""
        self._run_bandwidth_suite(board_cfg, gpio_chips, request, write=False)

