from __future__ import annotations

import os
import random
import statistics
import time

import pytest

from device_results import DeviceRunner

try:
    import serial
except ImportError:
    serial = None


class TestUart:
    """UART console loopback vs board YAML."""

    NO_DEVICES = "no uart.devices in board YAML"
    NO_BANDWIDTH = "no uart.bandwidth in board YAML"
    NO_OVERFLOW = "no uart.overflow in board YAML"

    HELLO_MSG = b"hello world\r\n"
    MAX_DRIVER_PAYLOAD_BYTES = 508
    PAYLOAD_SEED = 0xC0FFEE
    BW_CYCLES = 10
    BW_SLOW_CHECK_INTERVAL = 5
    BW_SLOW_THRESHOLD_FACTOR = 2.5
    READ_TIMEOUT_S = 30.0
    OVERFLOW_DRAIN_S = 2.0

    # 8N1 wire bits per byte: 1 start + 8 data + 1 stop. Loopback counts TX and RX.
    UART_BITS_PER_8N1_BYTE = 10
    UART_LOOPBACK_DIRECTIONS = 2

    @classmethod
    def get_expected_configs(cls, cfg: dict) -> dict:
        """Return ``uart.devices`` as ``{device_name: config}``."""
        return cfg.get("uart", {}).get("devices", {})

    @classmethod
    def get_loopback_device_labels(cls, cfg: dict) -> list[str]:
        """Return UART channel names with ``console`` and ``baud`` loopback config."""
        labels: list[str] = []
        for name, dev_cfg in cls.get_expected_configs(cfg).items():
            if not isinstance(dev_cfg, dict):
                continue
            if dev_cfg.get("console") and "baud" in dev_cfg:
                labels.append(name)
        return labels

    @classmethod
    def get_loopback_cfg(cls, cfg: dict, device_label: str) -> dict:
        """Return ``{console, baud, ...}`` for *device_label*."""
        dev_cfg = cls.get_expected_configs(cfg).get(device_label, {})
        if not isinstance(dev_cfg, dict):
            raise ValueError(f"uart.devices[{device_label!r}] must be a mapping")
        console = dev_cfg.get("console")
        if not console:
            raise ValueError(f"uart.devices[{device_label!r}] missing console")
        if "baud" not in dev_cfg:
            raise ValueError(
                f"uart.devices[{device_label!r}] must include baud when console is set"
            )
        baud = int(dev_cfg["baud"])
        if baud <= 0:
            raise ValueError(f"uart.devices[{device_label!r}] baud must be positive")
        return {**dev_cfg, "console": str(console), "baud": baud}

    @classmethod
    def bits_per_loopback(cls, payload_bytes: int) -> int:
        """8N1 wire bits for a loopback round-trip (TX + RX)."""
        return cls.UART_BITS_PER_8N1_BYTE * cls.UART_LOOPBACK_DIRECTIONS * payload_bytes

    @classmethod
    def min_loopback_ns(cls, payload_bytes: int, baud: int) -> int:
        """Minimum half-duplex serial time for TX then RX at *baud* (8N1)."""
        return (cls.bits_per_loopback(payload_bytes) * 1_000_000_000) // baud

    @classmethod
    def parse_bandwidth_cfg(cls, cfg: dict, device_label: str) -> dict | None:
        """Return ``{cycles, cases: [(payload_bytes, min_bps), ...]}`` or ``None``."""
        dev_cfg = cls.get_expected_configs(cfg).get(device_label, {})
        if not isinstance(dev_cfg, dict):
            return None
        raw = dev_cfg.get("bandwidth")
        if not raw:
            return None
        if not isinstance(raw, dict):
            raise ValueError(f"uart.devices[{device_label!r}].bandwidth must be a mapping")
        if "cases" not in raw:
            raise ValueError(f"uart.devices[{device_label!r}].bandwidth must include cases")

        cycles = int(raw.get("cycles", cls.BW_CYCLES))
        if cycles <= 0:
            raise ValueError(f"uart.devices[{device_label!r}].bandwidth.cycles must be positive")

        cases: list[tuple[int, int]] = []
        for case in raw["cases"] or []:
            if not isinstance(case, (list, tuple)) or len(case) != 2:
                raise ValueError(
                    f"uart.devices[{device_label!r}].bandwidth case must be "
                    f"[payload_bytes, min_bps]: {case!r}"
                )
            payload_bytes, min_bps = int(case[0]), int(case[1])
            if payload_bytes <= 0:
                raise ValueError(f"invalid payload size {payload_bytes}")
            if payload_bytes > cls.MAX_DRIVER_PAYLOAD_BYTES:
                raise ValueError(
                    f"uart.devices[{device_label!r}] payload size {payload_bytes} "
                    f"exceeds driver max {cls.MAX_DRIVER_PAYLOAD_BYTES}"
                )
            if min_bps < 0:
                raise ValueError(f"invalid min bps {min_bps}")
            cases.append((payload_bytes, min_bps))

        if not cases:
            return None
        return {"cycles": cycles, "cases": cases}

    @classmethod
    def parse_overflow_cfg(cls, cfg: dict, device_label: str) -> dict | None:
        """Return ``{payload_bytes, spam_writes}`` or ``None`` if unset."""
        dev_cfg = cls.get_expected_configs(cfg).get(device_label, {})
        if not isinstance(dev_cfg, dict):
            return None
        raw = dev_cfg.get("overflow")
        if not raw:
            return None
        if not isinstance(raw, dict):
            raise ValueError(f"uart.devices[{device_label!r}].overflow must be a mapping")
        payload_bytes = int(raw.get("payload_bytes", 0))
        if payload_bytes <= 0:
            raise ValueError(
                f"uart.devices[{device_label!r}].overflow.payload_bytes must be positive"
            )
        if payload_bytes > cls.MAX_DRIVER_PAYLOAD_BYTES:
            raise ValueError(
                f"uart.devices[{device_label!r}].overflow.payload_bytes {payload_bytes} "
                f"exceeds driver max {cls.MAX_DRIVER_PAYLOAD_BYTES}"
            )
        spam_writes = int(raw.get("spam_writes", 0))
        if spam_writes <= 0:
            raise ValueError(
                f"uart.devices[{device_label!r}].overflow.spam_writes must be positive"
            )
        return {"payload_bytes": payload_bytes, "spam_writes": spam_writes}

    @classmethod
    def read_timeout_s(cls, baud: int, nbytes: int) -> float:
        """Generous read timeout from 8N1 wire time (loopback TX + RX)."""
        wire_s = cls.bits_per_loopback(nbytes) / baud
        return max(wire_s * 5, cls.READ_TIMEOUT_S)

    @classmethod
    def loopback_payload(cls, nbytes: int, device_label: str, salt: int = 0) -> bytes:
        """Pseudo-random bytes unique per size/channel; any drop/dup misaligns."""
        seed = cls.PAYLOAD_SEED ^ (hash(device_label) & 0xFFFFFFFF) ^ salt
        return random.Random(seed).randbytes(nbytes)

    @staticmethod
    def _bw_case_key(device_label: str, payload_bytes: int) -> str:
        """Synthetic DeviceRunner key for one UART bandwidth case."""
        return f"{device_label} len={payload_bytes}"

    @classmethod
    def _format_bw_stats(cls, stats: dict, min_bps: int = 0) -> str:
        """Bandwidth stats suffix (no device label) for PASSED:/FAILED: folding."""
        bps = stats["mean_bps"]
        expected = f", expected >= {min_bps} bps" if min_bps else ""
        return (
            f"{bps:.0f} bps ({bps / 1000:.1f} kbps), "
            f"{stats['mean_ops']:.0f} round-trips/s{expected}"
        )

    @classmethod
    def _format_bw_summary(cls, label: str, stats: dict, min_bps: int = 0) -> str:
        """Compact labeled bandwidth line for multichannel reporting."""
        return f"{label}: {cls._format_bw_stats(stats, min_bps)}"

    @classmethod
    def open_console(cls, console: str, baud: int, write_timeout_s: float) -> serial.Serial:
        assert serial is not None
        return serial.Serial(
            console,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=0.5,
            write_timeout=write_timeout_s,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
        )

    @classmethod
    def _loopback_mismatch(
        cls, console: str, message: bytes, received: bytes, cycle: int | None = None
    ) -> str:
        prefix = f"cycle {cycle}: " if cycle is not None else ""
        limit = min(len(received), len(message))
        for i in range(limit):
            if received[i] != message[i]:
                return (
                    f"{prefix}loopback mismatch on {console!r} at offset {i}: "
                    f"sent 0x{message[i]:02x}, got 0x{received[i]:02x} "
                    f"({len(received)}/{len(message)} bytes)"
                )
        return (
            f"{prefix}loopback length mismatch on {console!r}: "
            f"sent {len(message)} bytes, got {len(received)} bytes"
        )

    @classmethod
    def _read_exact(cls, ser: serial.Serial, nbytes: int, timeout_s: float) -> bytes:
        deadline = time.monotonic() + timeout_s
        received = bytearray()
        while len(received) < nbytes and time.monotonic() < deadline:
            chunk = ser.read(nbytes - len(received))
            if chunk:
                received.extend(chunk)
        return bytes(received)

    @classmethod
    def loopback_round_trip(
        cls,
        ser: serial.Serial,
        console: str,
        payload: bytes,
        timeout_s: float,
        cycle: int | None = None,
    ) -> str | None:
        """Write *payload* on *ser*, read it back, compare."""
        ser.reset_input_buffer()
        ser.write(payload)
        ser.flush()
        received = cls._read_exact(ser, len(payload), timeout_s)
        if received != payload:
            return cls._loopback_mismatch(console, payload, received, cycle)
        return None

    @classmethod
    def measure_loopback_bw_on_serial(
        cls,
        ser: serial.Serial,
        console: str,
        baud: int,
        payload: bytes,
        cycles: int,
        expected_bps: int = 0,
    ) -> tuple[dict | None, str | None]:
        """Measure loopback bandwidth on an already-open console."""
        payload_bytes = len(payload)
        bits = cls.bits_per_loopback(payload_bytes)
        min_ns = cls.min_loopback_ns(payload_bytes, baud)
        timeout_s = cls.read_timeout_s(baud, payload_bytes)

        def stats(samples: list[int]) -> dict:
            effective = [max(s, min_ns) for s in samples]
            mean_ns = statistics.mean(effective)
            return {
                "min_bps": bits * 1_000_000_000 / max(effective),
                "max_bps": bits * 1_000_000_000 / min(effective),
                "mean_bps": bits * 1_000_000_000 / mean_ns,
                "mean_ops": 1_000_000_000 / mean_ns,
                "n": len(samples),
            }

        try:
            samples: list[int] = []
            for cycle in range(1, cycles + 1):
                t0 = time.perf_counter_ns()
                err = cls.loopback_round_trip(ser, console, payload, timeout_s, cycle=cycle - 1)
                if err:
                    return None, err
                samples.append(time.perf_counter_ns() - t0)
                if (
                    expected_bps > 0
                    and cycle >= cls.BW_SLOW_CHECK_INTERVAL
                    and cycle % cls.BW_SLOW_CHECK_INTERVAL == 0
                ):
                    if stats(samples)["mean_bps"] < expected_bps / cls.BW_SLOW_THRESHOLD_FACTOR:
                        break
        except serial.SerialException as e:
            return None, f"serial I/O failed on {console!r}: {e}"

        return stats(samples), None

    @classmethod
    def measure_loopback_bw(
        cls, console: str, baud: int, payload: bytes, cycles: int, expected_bps: int = 0
    ) -> tuple[dict | None, str | None]:
        """Repeated validated loopback round-trips; stats in effective wire bps.

        Elapsed time is floored at the minimum 8N1 TX+RX serial time so pipelined
        echo (RX starting before TX finishes) cannot report above the line rate.
        """
        assert serial is not None
        timeout_s = cls.read_timeout_s(baud, len(payload))

        try:
            ser = cls.open_console(console, baud, timeout_s)
        except serial.SerialException as e:
            return None, f"failed to open {console!r}: {e}"

        try:
            return cls.measure_loopback_bw_on_serial(
                ser, console, baud, payload, cycles, expected_bps
            )
        finally:
            ser.close()

    @classmethod
    def spam_console(cls, console: str, baud: int, payload: bytes, spam_writes: int) -> str | None:
        """Write *spam_writes* payloads without reading; drain and close."""
        assert serial is not None
        timeout_s = cls.read_timeout_s(baud, len(payload))
        try:
            ser = cls.open_console(console, baud, timeout_s)
        except serial.SerialException as e:
            return f"failed to open {console!r}: {e}"

        try:
            ser.reset_input_buffer()
            ser.reset_output_buffer()
            for _ in range(spam_writes):
                ser.write(payload)
            ser.flush()

            deadline = time.monotonic() + cls.OVERFLOW_DRAIN_S
            while time.monotonic() < deadline:
                if not ser.read(4096):
                    time.sleep(0.05)
            return None
        except serial.SerialException as e:
            return f"serial spam failed on {console!r}: {e}"
        finally:
            ser.close()

    @classmethod
    def console_loopback(cls, console: str, baud: int, message: bytes) -> str | None:
        """One-shot write/read on a fresh open/close."""
        assert serial is not None
        timeout_s = cls.read_timeout_s(baud, len(message))
        try:
            ser = cls.open_console(console, baud, timeout_s)
        except serial.SerialException as e:
            return f"failed to open {console!r}: {e}"
        try:
            return cls.loopback_round_trip(ser, console, message, timeout_s)
        except serial.SerialException as e:
            return f"serial I/O failed on {console!r}: {e}"
        finally:
            ser.close()

    # ------------------------- UART Tests -------------------------
    def test_uart_loopback_bandwidth(self, board_cfg, uart_devices, request) -> None:
        """Each ``uart.bandwidth`` case must meet effective wire bps with validated echo."""
        labels = self.get_loopback_device_labels(board_cfg)
        if not labels:
            pytest.skip(self.NO_DEVICES)
        if serial is None:
            pytest.skip("pyserial not installed")

        runner = DeviceRunner(
            board_cfg,
            "uart",
            "uart_loopback_bandwidth",
            skip=self.NO_DEVICES,
            finding="F23",
            request=request,
        )
        for device_label in labels:
            bw_cfg = self.parse_bandwidth_cfg(board_cfg, device_label)
            if bw_cfg is None:
                runner.run(device_label, lambda: None, when=False, skip=self.NO_BANDWIDTH)
                continue

            for payload_bytes, min_bps in bw_cfg["cases"]:
                case_key = self._bw_case_key(device_label, payload_bytes)

                def _one(
                    label=device_label,
                    length=payload_bytes,
                    floor=min_bps,
                    cycles=bw_cfg["cycles"],
                    key=case_key,
                ) -> None:
                    loopback = self.get_loopback_cfg(board_cfg, label)
                    console = loopback["console"]
                    baud = loopback["baud"]
                    discovered = uart_devices.get(label)
                    if discovered is None:
                        pytest.fail(f"UART device not discovered for {label}")
                    console_name = os.path.basename(console)
                    if discovered not in (console, console_name):
                        pytest.fail(
                            f"UART console mismatch for {label}: "
                            f"discovered {discovered!r}, YAML console {console!r}"
                        )
                    if not os.path.exists(console):
                        pytest.fail(f"UART console {console!r} does not exist")

                    payload = self.loopback_payload(length, label, salt=length)
                    stats, err = self.measure_loopback_bw(console, baud, payload, cycles, floor)
                    if err:
                        pytest.fail(err)
                    assert stats is not None
                    summary = self._format_bw_stats(stats, floor)
                    if stats["mean_bps"] < floor:
                        pytest.fail(summary)
                    runner.add_detail(key, summary)

                runner.run(case_key, _one)

        runner.finish()

    def test_uart_overflow(self, board_cfg, uart_devices, request) -> None:
        """Spam writes without reading; UART must still answer a hello-world."""
        labels = self.get_loopback_device_labels(board_cfg)
        if not labels:
            pytest.skip(self.NO_DEVICES)
        if serial is None:
            pytest.skip("pyserial not installed")

        runner = DeviceRunner(
            board_cfg, "uart", "uart_overflow", skip=self.NO_DEVICES, finding="F23", request=request
        )
        for device_label in labels:
            ov_cfg = self.parse_overflow_cfg(board_cfg, device_label)

            def _one(label=device_label, cfg=ov_cfg) -> None:
                loopback = self.get_loopback_cfg(board_cfg, label)
                console = loopback["console"]
                baud = loopback["baud"]
                discovered = uart_devices.get(label)
                if discovered is None:
                    pytest.fail(f"UART device not discovered for {label}")
                console_name = os.path.basename(console)
                if discovered not in (console, console_name):
                    pytest.fail(
                        f"UART console mismatch for {label}: "
                        f"discovered {discovered!r}, YAML console {console!r}"
                    )
                if not os.path.exists(console):
                    pytest.fail(f"UART console {console!r} does not exist")

                payload = self.loopback_payload(cfg["payload_bytes"], label, salt=0xDEAD)
                err = self.spam_console(console, baud, payload, cfg["spam_writes"])
                assert err is None, err

                err = self.console_loopback(console, baud, self.HELLO_MSG)
                assert err is None, f"UART not responsive after overflow spam on {console!r}: {err}"

            runner.run(device_label, _one, when=ov_cfg is not None, skip=self.NO_OVERFLOW)
        runner.finish()

