#
# Concurrent multi-channel bandwidth tests (I2C, GPIO, UART at the same time).
#
# Board config: ``multichannel`` section in boards/<board>.yaml
#   scaling_factor: non-zero multiplier on solo YAML floors; parallel throughput must meet
#   solo_floor * scaling_factor (``i2c.bandwidth`` min bps, ``gpio.bandwidth`` ops/s,
#   ``uart.devices.*.bandwidth`` min bps). 0 (or unset) skips.
#
# Runs only during a full test run (not a ``--suite``). Requires at least two of:
# ``i2c.bandwidth`` on a discovered bus, ``gpio.devices`` on a discovered chip, or
# ``uart.devices.*.bandwidth`` on a discovered channel. Each session starts all active workers
# together; faster channels repeat sweeps until every channel has finished its first sweep (full
# overlap window). Results are taken from the first sweep of each channel in that session.

from __future__ import annotations

from concurrent.futures import ThreadPoolExecutor, as_completed
import os
import threading

import pytest

import deviations
from device_results import test_message
from test_gpio import TestGpio
from test_i2c import TestI2c
from test_uart import TestUart

try:
    import gpiod
except ImportError:
    gpiod = None

try:
    import serial
except ImportError:
    serial = None

try:
    import smbus2
except ImportError:
    smbus2 = None


class TestMultichannel:
    """I2C, GPIO, and UART bandwidth sweeps under mutual load."""

    @staticmethod
    def _i2c_key(bus_name: str, read_len: int, addr: int) -> str:
        return f"{bus_name}|{read_len}|{addr}"

    @staticmethod
    def _gpio_key(chip_label: str, kind: str, offset: int) -> str:
        return f"{chip_label}|{kind}|{offset}"

    @staticmethod
    def _uart_key(device_label: str, payload_bytes: int) -> str:
        return f"{device_label}|{payload_bytes}"

    @classmethod
    def _has_i2c_bandwidth(cls, board_cfg: dict, i2c_buses: dict[str, int]) -> bool:
        for target in TestI2c.parse_bandwidth_cfg(board_cfg.get("i2c", {})):
            if target["cases"] and target["bus_name"] in i2c_buses:
                return True
        return False

    @classmethod
    def _has_gpio_lines(cls, board_cfg: dict) -> bool:
        for label in board_cfg.get("gpio", {}).get("devices", {}) or {}:
            lines = TestGpio.expected_gpioinfo(board_cfg, label)
            if any(line["kind"] == "gpio" for line in lines.values()):
                return True
        return False

    @classmethod
    def _gpio_bw_offsets(cls, board_cfg: dict, label: str) -> tuple[list[int], list[int]]:
        """Return write/read offsets for bandwidth (``gpio`` rows only, like solo tests)."""
        pins = TestGpio.chip_pins(board_cfg, label)
        return pins["outputs"], pins["gpio"]

    @classmethod
    def _has_uart_bandwidth(cls, board_cfg: dict) -> bool:
        for label in TestUart.get_expected_configs(board_cfg):
            if TestUart.parse_bandwidth_cfg(board_cfg, label) is None:
                continue
            return True
        return False

    @classmethod
    def _active_channels(
        cls,
        board_cfg: dict,
        i2c_buses: dict[str, int],
        gpio_chips: dict[str, str],
        uart_devices: dict[str, str],
    ) -> tuple[bool, bool, bool]:
        has_i2c = cls._has_i2c_bandwidth(board_cfg, i2c_buses)
        has_gpio = cls._has_gpio_lines(board_cfg)
        has_uart = cls._has_uart_bandwidth(board_cfg)
        return has_i2c, has_gpio, has_uart

    @classmethod
    def _i2c_sweep(cls, i2c_cfg: dict, i2c_buses: dict[str, int]) -> dict[str, dict]:
        """Every ``i2c.bandwidth`` case via :meth:`TestI2c.measure_read_bw`."""
        results: dict[str, dict] = {}
        for target in TestI2c.parse_bandwidth_cfg(i2c_cfg):
            bus_name = target["bus_name"]
            addr = target["addr"]
            if bus_name not in i2c_buses:
                continue
            bus_num = i2c_buses[bus_name]
            for read_len, min_bps in target["cases"]:
                stats = TestI2c.measure_read_bw(bus_num, addr, read_len, TestI2c.BW_CYCLES, 0)
                key = cls._i2c_key(bus_name, read_len, addr)
                label = f"{bus_name} (i2c-{bus_num}) len={read_len} @{addr:#x}"
                results[key] = {"label": label, "stats": stats, "min_bps": min_bps}
        return results

    @classmethod
    def _gpio_sweep(cls, board_cfg: dict, gpio_chips: dict[str, str]) -> dict[str, dict]:
        """Measure ``gpio`` row bandwidth via :meth:`TestGpio.measure_bw` (skip ``led`` rows)."""
        results: dict[str, dict] = {}
        devices = board_cfg.get("gpio", {}).get("devices", {}) or {}
        for label, cfg in devices.items():
            if not cfg:
                continue
            write_offs, read_offs = cls._gpio_bw_offsets(board_cfg, label)
            chip_name = gpio_chips.get(label)
            if chip_name is None:
                error = f"{label}: GPIO chip not found"
                for off in write_offs:
                    key = cls._gpio_key(label, "write", off)
                    results[key] = {
                        "label": f"{label} line {off}",
                        "stats": None,
                        "kind": "write",
                        "chip": label,
                        "error": error,
                    }
                for off in read_offs:
                    key = cls._gpio_key(label, "read", off)
                    results[key] = {
                        "label": f"{label} line {off}",
                        "stats": None,
                        "kind": "read",
                        "chip": label,
                        "error": error,
                    }
                continue
            for off in write_offs:
                stats = TestGpio.measure_bw(
                    chip_name, off, TestGpio.BW_CYCLES, TestGpio.BW_WARMUP, write=True
                )
                key = cls._gpio_key(label, "write", off)
                results[key] = {
                    "label": f"{label} line {off}",
                    "stats": stats,
                    "kind": "write",
                    "chip": label,
                }
            for off in read_offs:
                stats = TestGpio.measure_bw(
                    chip_name, off, TestGpio.BW_CYCLES, TestGpio.BW_WARMUP, write=False
                )
                key = cls._gpio_key(label, "read", off)
                results[key] = {
                    "label": f"{label} line {off}",
                    "stats": stats,
                    "kind": "read",
                    "chip": label,
                }
        return results

    @classmethod
    def _uart_sweep(cls, board_cfg: dict, uart_devices: dict[str, str]) -> dict[str, dict]:
        """Run ``uart.devices.*.bandwidth`` via :meth:`TestUart.measure_loopback_bw_on_serial`."""
        results: dict[str, dict] = {}
        for label in TestUart.get_expected_configs(board_cfg):
            bw_cfg = TestUart.parse_bandwidth_cfg(board_cfg, label)
            if bw_cfg is None:
                continue
            loopback = TestUart.get_loopback_cfg(board_cfg, label)
            console = loopback["console"]
            baud = loopback["baud"]
            cycles = bw_cfg["cycles"]
            cases = bw_cfg["cases"]

            for payload_bytes, min_bps in cases:
                key = cls._uart_key(label, payload_bytes)
                results[key] = {
                    "label": f"{label} ({console}) len={payload_bytes}",
                    "stats": None,
                    "min_bps": min_bps,
                }

            if label not in uart_devices:
                err = f"{label}: UART device not found"
                for payload_bytes, _ in cases:
                    results[cls._uart_key(label, payload_bytes)]["error"] = err
                continue

            if not os.path.exists(console):
                err = f"UART console {console!r} does not exist"
                for payload_bytes, _ in cases:
                    results[cls._uart_key(label, payload_bytes)]["error"] = err
                continue

            max_payload = max(payload_bytes for payload_bytes, _ in cases)
            open_timeout = TestUart.read_timeout_s(baud, max_payload)
            try:
                ser = TestUart.open_console(console, baud, open_timeout)
            except serial.SerialException as e:
                err = f"failed to open {console!r}: {e}"
                for payload_bytes, _ in cases:
                    results[cls._uart_key(label, payload_bytes)]["error"] = err
                continue

            try:
                for payload_bytes, min_bps in cases:
                    key = cls._uart_key(label, payload_bytes)
                    payload = TestUart.loopback_payload(payload_bytes, label, salt=payload_bytes)
                    stats, err = TestUart.measure_loopback_bw_on_serial(
                        ser, console, baud, payload, cycles, 0
                    )
                    entry = results[key]
                    if err:
                        entry["error"] = err
                    else:
                        entry["stats"] = stats
            except serial.SerialException as e:
                err = f"serial I/O failed on {console!r}: {e}"
                for payload_bytes, _ in cases:
                    key = cls._uart_key(label, payload_bytes)
                    if results[key].get("stats") is None and "error" not in results[key]:
                        results[key]["error"] = err
            finally:
                ser.close()
        return results

    @classmethod
    def _session_worker(
        cls,
        name: str,
        active_names: frozenset[str],
        sweep_fn,
        start_barrier: threading.Barrier,
        session_done: threading.Event,
        completions: dict[str, int],
        lock: threading.Lock,
    ) -> dict[str, dict]:
        """Run sweeps until every channel finishes once; return the first sweep."""
        start_barrier.wait()
        sweeps: list[dict[str, dict]] = []
        while True:
            sweeps.append(sweep_fn())
            with lock:
                completions[name] = completions.get(name, 0) + 1
                if all(completions.get(n, 0) >= 1 for n in active_names):
                    session_done.set()
            if session_done.is_set():
                if len(sweeps) > 1:
                    sweeps = sweeps[:-1]
                break
        return sweeps[0]

    @classmethod
    def _run_parallel(
        cls,
        board_cfg: dict,
        i2c_buses: dict[str, int],
        gpio_chips: dict[str, str],
        uart_devices: dict[str, str],
        has_i2c: bool,
        has_gpio: bool,
        has_uart: bool,
    ) -> tuple[dict[str, dict], dict[str, dict], dict[str, dict]]:
        """Run one overlap session; return first-sweep ``(i2c, gpio, uart)`` results."""
        active = frozenset(
            n
            for n, enabled in (("i2c", has_i2c), ("gpio", has_gpio), ("uart", has_uart))
            if enabled
        )
        start_barrier = threading.Barrier(len(active))
        session_done = threading.Event()
        completions: dict[str, int] = {}
        lock = threading.Lock()

        i2c_results: dict[str, dict] = {}
        gpio_results: dict[str, dict] = {}
        uart_results: dict[str, dict] = {}

        def i2c_worker() -> None:
            nonlocal i2c_results
            i2c_results = cls._session_worker(
                "i2c",
                active,
                lambda: cls._i2c_sweep(board_cfg.get("i2c", {}), i2c_buses),
                start_barrier,
                session_done,
                completions,
                lock,
            )

        def gpio_worker() -> None:
            nonlocal gpio_results
            gpio_results = cls._session_worker(
                "gpio",
                active,
                lambda: cls._gpio_sweep(board_cfg, gpio_chips),
                start_barrier,
                session_done,
                completions,
                lock,
            )

        def uart_worker() -> None:
            nonlocal uart_results
            uart_results = cls._session_worker(
                "uart",
                active,
                lambda: cls._uart_sweep(board_cfg, uart_devices),
                start_barrier,
                session_done,
                completions,
                lock,
            )

        workers: list[tuple[str, object]] = []
        if has_i2c:
            workers.append(("i2c", i2c_worker))
        if has_gpio:
            workers.append(("gpio", gpio_worker))
        if has_uart:
            workers.append(("uart", uart_worker))

        with ThreadPoolExecutor(max_workers=len(workers)) as executor:
            futures = {executor.submit(fn): name for name, fn in workers}
            for fut in as_completed(futures):
                fut.result()

        return i2c_results, gpio_results, uart_results

    @staticmethod
    def _mark_line(line: str, failed_lines: set[str] | None) -> str:
        if failed_lines is None:
            return f"  {line}"
        tag = "FAIL" if line in failed_lines else "ok  "
        return f"  {tag}  {line}"

    @classmethod
    def _results_blocks(
        cls,
        i2c_lines: list[str],
        gpio_write: list[tuple[str, list[str]]],
        gpio_read: list[tuple[str, list[str]]],
        uart_lines: list[str],
        failed_lines: set[str] | None = None,
    ) -> list[str]:
        """Build grouped parallel bandwidth blocks separated by blank lines."""
        blocks: list[str] = []
        if i2c_lines:
            lines = ["I2C read:"]
            lines.extend(cls._mark_line(line, failed_lines) for line in i2c_lines)
            blocks.append("\n".join(lines))
        for chip, chip_lines in gpio_write:
            lines = [f"GPIO write ({chip}):"]
            lines.extend(cls._mark_line(line, failed_lines) for line in chip_lines)
            blocks.append("\n".join(lines))
        for chip, chip_lines in gpio_read:
            lines = [f"GPIO read ({chip}):"]
            lines.extend(cls._mark_line(line, failed_lines) for line in chip_lines)
            blocks.append("\n".join(lines))
        if uart_lines:
            lines = ["UART loopback:"]
            lines.extend(cls._mark_line(line, failed_lines) for line in uart_lines)
            blocks.append("\n".join(lines))
        return blocks

    @classmethod
    def _results_text(
        cls,
        i2c_lines: list[str],
        gpio_write: list[tuple[str, list[str]]],
        gpio_read: list[tuple[str, list[str]]],
        uart_lines: list[str],
        *,
        failed_lines: set[str] | None = None,
        indent: str = "",
    ) -> str:
        blocks = cls._results_blocks(i2c_lines, gpio_write, gpio_read, uart_lines, failed_lines)
        if not blocks:
            return ""
        text = "\n\n".join(blocks)
        if not indent:
            return text
        return "\n\n".join(
            "\n".join(f"{indent}{line}" for line in block.splitlines()) for block in blocks
        )

    @staticmethod
    def _failure_block(
        factor: float,
        failures: list[str],
        i2c_lines: list[str],
        gpio_write: list[tuple[str, list[str]]],
        gpio_read: list[tuple[str, list[str]]],
        uart_lines: list[str],
        failed_lines: set[str],
    ) -> str:
        n = len(failures)
        header = (
            f"Parallel bandwidth below scaling_factor ({factor}): "
            f"{n} case{'s' if n != 1 else ''} failed"
        )
        body = TestMultichannel._results_text(
            i2c_lines, gpio_write, gpio_read, uart_lines, failed_lines=failed_lines, indent="  "
        )
        standalone_failures = [failure for failure in failures if failure not in failed_lines]
        if standalone_failures:
            standalone = "\n".join(f"  FAIL  {failure}" for failure in standalone_failures)
            if body:
                body = f"{body}\n\n{standalone}"
            else:
                body = standalone
        if body:
            return f"{header}\n\n{body}"
        return header

    @staticmethod
    def _report(
        request,
        factor: float,
        i2c_lines: list[str],
        gpio_write: list[tuple[str, list[str]]],
        gpio_read: list[tuple[str, list[str]]],
        uart_lines: list[str],
    ) -> None:
        body = TestMultichannel._results_text(i2c_lines, gpio_write, gpio_read, uart_lines)
        if not body:
            return
        test_message(
            request,
            details=[f"Parallel bandwidth (scaling_factor={factor}):", "", *body.splitlines()],
        )

    # ------------------------- Multichannel Tests -------------------------

    def test_multichannel_parallel_bandwidth(
        self, board_cfg, i2c_buses, gpio_chips, uart_devices, request
    ) -> None:
        """I2C/GPIO/UART floors must hold while channels run together."""
        factor = board_cfg.get("multichannel", {}).get("scaling_factor")
        if factor is None:
            pytest.skip("no multichannel.scaling_factor configured")
        factor = float(factor)
        if factor == 0:
            pytest.skip("multichannel.scaling_factor is 0")
        if factor < 0:
            pytest.fail("multichannel.scaling_factor must be positive")

        has_i2c, has_gpio, has_uart = self._active_channels(
            board_cfg, i2c_buses, gpio_chips, uart_devices
        )
        if sum((has_i2c, has_gpio, has_uart)) < 2:
            pytest.skip("need at least two of i2c.bandwidth, gpio.devices, uart.bandwidth")

        if has_i2c and smbus2 is None:
            pytest.skip("smbus2 not installed")
        if has_gpio and gpiod is None:
            pytest.skip("python3-gpiod not installed")
        if has_uart and serial is None:
            pytest.skip("pyserial not installed")

        expected_gpio_ops = board_cfg.get("gpio", {}).get("bandwidth", 0)
        par_i2c, par_gpio, par_uart = self._run_parallel(
            board_cfg, i2c_buses, gpio_chips, uart_devices, has_i2c, has_gpio, has_uart
        )

        failures: list[str] = []
        failed_lines: set[str] = set()
        i2c_lines: list[str] = []
        uart_lines: list[str] = []
        by_chip_write: dict[str, list[str]] = {}
        by_chip_read: dict[str, list[str]] = {}

        for key, entry in sorted(par_i2c.items()):
            label = entry["label"]
            stats = entry["stats"]
            min_bps = entry["min_bps"]
            if entry.get("error"):
                failures.append(entry["error"])
                continue
            if stats is None:
                read_len = int(key.split("|")[1])
                if read_len == 0:
                    failures.append(f"{label}: bus.read failed")
                else:
                    i2c_lines.append(f"{label}: skipped (unsupported or NACK)")
                continue
            summary = TestI2c._format_bw_summary(label, stats)
            i2c_lines.append(summary)
            floor = min_bps * factor
            if stats["mean_bps"] < floor:
                failures.append(summary)
                failed_lines.add(summary)

        for entry in par_gpio.values():
            stats = entry["stats"]
            label = entry["label"]
            kind = entry["kind"]
            chip = entry["chip"]
            if entry.get("error"):
                failures.append(f"GPIO {kind} {label}: {entry['error']}")
                continue
            if stats is None:
                failures.append(f"GPIO {kind} {label}: measurement failed")
                continue
            line = TestGpio._format_mean_ops(stats[4], label)
            if kind == "write":
                by_chip_write.setdefault(chip, []).append(line)
            else:
                by_chip_read.setdefault(chip, []).append(line)
            if expected_gpio_ops:
                floor = expected_gpio_ops * factor
                if stats[4] < floor:
                    failures.append(line)
                    failed_lines.add(line)

        for key, entry in sorted(par_uart.items()):
            label = entry["label"]
            stats = entry["stats"]
            min_bps = entry["min_bps"]
            if entry.get("error"):
                line = f"{label}: {entry['error']}"
                uart_lines.append(line)
                failures.append(f"UART {line}")
                failed_lines.add(line)
                continue
            if stats is None:
                line = f"{label}: measurement failed"
                uart_lines.append(line)
                failures.append(f"UART {line}")
                failed_lines.add(line)
                continue
            summary = TestUart._format_bw_summary(label, stats)
            uart_lines.append(summary)
            floor = min_bps * factor
            if stats["mean_bps"] < floor:
                failures.append(summary)
                failed_lines.add(summary)

        gpio_write = sorted(by_chip_write.items())
        gpio_read = sorted(by_chip_read.items())

        if failures:
            block = self._failure_block(
                factor, failures, i2c_lines, gpio_write, gpio_read, uart_lines, failed_lines
            )
            if reason := deviations.declared_note("F24"):
                # An xfailed item has no FAILURES section, so attach the same
                # block under the result line instead.
                test_message(request, details=block.splitlines())
                pytest.xfail(reason)
            assert not failures, block
        self._report(request, factor, i2c_lines, gpio_write, gpio_read, uart_lines)

