# Board config: ``i2c`` section in boards/<board>.yaml
#   devices:            bus_name -> [7-bit addresses]
#   fail_on_unexpected: bus_name -> bool; fail i2cdetect on extra addresses
#   i2c_eeprom:         bus_name -> {addr: [eeprom_type, size]}
#   bandwidth:          bus_name -> {addr, cases: [[read_bytes, min_mean_bps], ...]}; {} skips
