                if bus_name not in expected_buses:
                    runner.failed(case_key, "bus not in i2c.devices config")
                    continue

                def _one(
                    name=bus_name, a=addr, length=read_len, floor=min_bps, key=case_key
                ) -> None:
                    stats = self.measure_read_bw(i2c_buses[name], a, length, self.BW_CYCLES, floor)
                    if stats is None:
                        pytest.fail("bus.read failed")
                    summary = self._format_bw_stats(stats, floor)
                    if stats["mean_bps"] < floor:
                        pytest.fail(summary)
                    runner.add_detail(key, summary)

                runner.run(case_key, _one, when=bus_name in i2c_buses, skip=self.DISCOVERY_SKIP)

        runner.finish()

