    @staticmethod
    def _eeprom_targets(runner: DeviceRunner, i2c_eeproms: dict) -> dict[str, dict]:
        """Return per-EEPROM contexts; record a suite failure when setup could not run."""
        if err := i2c_eeproms.get(SETUP_ERROR_KEY):
            runner.failed(SUITE, f"EEPROM setup failed: {err}")
            return {}
        return {k: v for k, v in i2c_eeproms.items() if not k.startswith("_")}

    def test_eeprom_sysfs(self, board_cfg, i2c_eeproms: dict, request) -> None:
        """at24 device directory and eeprom attribute must exist in sysfs."""
        if not i2c_eeproms:
            pytest.skip(self.NO_EEPROM)
        runner = DeviceRunner(
            board_cfg,
            "i2c",
            "eeprom_sysfs",
            requires=[("i2c", "i2cdetect_expected_addresses", self._parent_bus_key)],
            request=request,
        )
        for eeprom_id, ctx in self._eeprom_targets(runner, i2c_eeproms).items():

            def _one(c=ctx) -> None:
                assert os.path.isdir(c["dev_sysfs"]), f"Missing {c['dev_sysfs']}"
                assert os.path.exists(c["eeprom_path"]), f"Missing {c['eeprom_path']}"

            runner.run(eeprom_id, _one)
