                exp = c["expected_size"]
                assert size == exp, f"EEPROM size: {size}, expected {exp}"

            runner.run(eeprom_id, _one)
        runner.finish()

    def test_eeprom_write_read(self, board_cfg, i2c_eeproms: dict, request) -> None:
        """Write incrementing 32-bit values across the full EEPROM, then verify."""
        if not i2c_eeproms:
            pytest.skip(self.NO_EEPROM)
        runner = DeviceRunner(
            board_cfg,
            "i2c",
            "eeprom_write_read",
            requires=[("i2c", "eeprom_size")],
            request=request,
        )
        for eeprom_id, ctx in self._eeprom_targets(runner, i2c_eeproms).items():

            def _one(c=ctx) -> None:
                ep = c["eeprom_path"]
                size = c["expected_size"]
                num_words = size // 4
                base = int(time.time()) & 0xFFFFFFFF

                pattern = struct.pack(
                    f"<{num_words}I", *(((base + i) & 0xFFFFFFFF) for i in range(num_words))
                )
                tail = size % 4
                if tail:
                    pattern += bytes(tail)

                page_size = c["page_size"]
                fd = os.open(ep, os.O_RDWR)
                try:
                    for off in range(0, len(pattern), page_size):
                        chunk = pattern[off : off + page_size]
                        nw = os.pwrite(fd, chunk, off)
                        assert nw == len(chunk), (
                            f"EEPROM pwrite at 0x{off:04x} wrote {nw}/{len(chunk)} bytes"
                        )
                    time.sleep(0.5)
                    rd = os.pread(fd, size, 0)
                    assert len(rd) == size, f"EEPROM pread returned {len(rd)}/{size} bytes"
                finally:
                    os.close(fd)

                mismatches = []
                for i in range(num_words):
                    off = i * 4
                    expected = struct.pack("<I", (base + i) & 0xFFFFFFFF)
                    actual = rd[off : off + 4]
                    if actual != expected:
                        mismatches.append(
                            f"offset 0x{off:04x}: expected {expected.hex()} got {actual.hex()}"
                        )
                assert not mismatches, (
                    f"{len(mismatches)}/{num_words} EEPROM words mismatched:\n"
                    + "\n".join(mismatches[:20])
                )

            runner.run(eeprom_id, _one)
        runner.finish()

