# GPIO IRQ tests (loopback stimulus).
#
# Board config: ``gpio`` section in boards/<board>.yaml
#   irq_loopback: chip_label -> {test_id: [drive, listen]}
#
# Requires GPIO enumeration to pass first (full run or ``--suite irq``, which
# also runs the GPIO suite as a prerequisite).
#
# Usage: --suite irq

from __future__ import annotations

import time

import pytest

from device_results import DeviceRunner
from test_gpio import TestGpio

try:
    import gpiod
    from gpiod.line import Direction, Edge, Value
except ImportError:
    gpiod = None


class TestIrq:
    """GPIO edge IRQ tests; configuration lives under ``gpio.irq_*``."""

    NO_LOOPBACK_PAIRS = "no gpio.irq_loopback pairs in board YAML"
    DISCOVERY_SKIP = TestGpio.DISCOVERY_SKIP

    IRQ_TIMEOUT_S = 1.0  # USB round-trip; edge events are not instant

    @classmethod
    def get_expected_configs(cls, cfg: dict) -> dict:
        """Return chip labels that declare ``irq_loopback``."""
        labels = (cfg.get("gpio", {}).get("irq_loopback") or {}).keys()
        return {label: {} for label in sorted(labels)}

    @classmethod
    def _resolve_line(cls, dev_cfg: dict, ref) -> int | None:
        """Map a YAML line reference (offset int or line-name str) to an offset."""
        if isinstance(ref, int):
            return ref if ref in dev_cfg else None
        for off, entry in dev_cfg.items():
            if entry and entry[0] == ref:
                return off
        return None

    @classmethod
    def check_irq_loopback(cls, chip_name: str, drive: int, listen: int) -> list[str]:
        """Drive *drive* high then low and expect rising/falling edges on *listen*."""
        try:
            in_req = gpiod.request_lines(
                f"/dev/{chip_name}",
                consumer="lstp_qa_irq_in",
                config={
                    listen: gpiod.LineSettings(direction=Direction.INPUT, edge_detection=Edge.BOTH)
                },
            )
        except OSError as e:
            return [f"could not request input line {listen}: {e}"]

        try:
            out_req = gpiod.request_lines(
                f"/dev/{chip_name}",
                consumer="lstp_qa_irq_out",
                config={
                    drive: gpiod.LineSettings(
                        direction=Direction.OUTPUT, output_value=Value.INACTIVE
                    )
                },
            )
        except OSError as e:
            in_req.release()
            return [f"could not request output line {drive}: {e}"]

        problems: list[str] = []
        try:
            time.sleep(0.05)
            while in_req.wait_edge_events(0):
                in_req.read_edge_events()

            for label, value, want in (
                ("rising", Value.ACTIVE, gpiod.EdgeEvent.Type.RISING_EDGE),
                ("falling", Value.INACTIVE, gpiod.EdgeEvent.Type.FALLING_EDGE),
            ):
                out_req.set_value(drive, value)
                if not in_req.wait_edge_events(cls.IRQ_TIMEOUT_S):
                    problems.append(f"{label}: no edge within {cls.IRQ_TIMEOUT_S}s")
                    continue
                got = [e.event_type for e in in_req.read_edge_events()]
                if want not in got:
                    problems.append(f"{label}: expected {want!r}, got {got!r}")
        finally:
            out_req.release()
            in_req.release()
        return problems

    def test_irq_loopback(self, board_cfg, gpio_chips, request) -> None:
        """Shorted output->input pairs must deliver one rising + one falling IRQ."""
        if gpiod is None:
            pytest.skip("python3-gpiod not installed")
        labels = sorted((board_cfg.get("gpio", {}).get("irq_loopback") or {}).keys())
        if not labels:
            pytest.skip(self.NO_LOOPBACK_PAIRS)

        runner = DeviceRunner(
            board_cfg,
            "irq",
            "irq_loopback",
            requires=[("gpio", "gpio_line_directions")],
            skip=self.NO_LOOPBACK_PAIRS,
            request=request,
        )

        for device_label in labels:
            pairs = board_cfg.get("gpio", {}).get("irq_loopback", {}).get(device_label, {})

            def _one(label=device_label, pair_map=pairs) -> None:
                dev_cfg = board_cfg.get("gpio", {}).get("devices", {}).get(label, {})
                chip_name = gpio_chips[label]
                failures: list[str] = []
                for test_id, pair in pair_map.items():
                    drive = self._resolve_line(dev_cfg, pair[0])
                    listen = self._resolve_line(dev_cfg, pair[1])
                    if drive is None or listen is None:
                        failures.append(f"{test_id}: unknown line(s) {pair!r}")
                        continue
                    if drive == listen:
                        failures.append(f"{test_id}: drive and listen are the same line {drive}")
                        continue
                    for p in self.check_irq_loopback(chip_name, drive, listen):
                        failures.append(f"{test_id} (drive={pair[0]}, listen={pair[1]}): {p}")
                assert not failures, "IRQ loopback failures:\n" + "\n".join(failures)

            runner.run(
                device_label,
                _one,
                when=device_label in gpio_chips and bool(pairs),
                skip=(
                    self.DISCOVERY_SKIP
                    if device_label not in gpio_chips
                    else self.NO_LOOPBACK_PAIRS
                ),
            )
        runner.finish()
